module e603_rst_ctrl (
  output hart_under_reset,
  input  clk_aon,    
  input  por_reset_n,
  input  core_reset_n,
  input  reset_bypass,  
  
  output rst_core,
  
  output rst_por, 
  output rst_aon 
);
wire  rst_n_a;
wire  rst_n_por_a;
    
wire  byp_core_reset_n = reset_bypass ? 1'b1 : 
                       (
                         core_reset_n
                       );
assign rst_n_a = (por_reset_n & byp_core_reset_n);
assign rst_n_por_a = (por_reset_n);
wire rst_n_sync;
wire rst_n_por_sync;
      
      
e603_reset_sync #(
    .RST_SYNC_LEVEL(2)
)u_reset_sync(
  .clk      (clk_aon),
  .rst_n_a  (rst_n_a),
  .reset_bypass(reset_bypass),
  .rst_n_sync(rst_n_sync)   
);
e603_reset_sync #(
    .RST_SYNC_LEVEL(2)
)u_reset_por_sync(
  .clk      (clk_aon),
  .rst_n_a  (rst_n_por_a),
  .reset_bypass(reset_bypass),
  .rst_n_sync(rst_n_por_sync)   
);
    
    
    
    
     
   
 assign rst_core = rst_n_sync;
 
   
 assign rst_aon = rst_n_sync;
 assign rst_por = rst_n_por_sync;
 
 
 
 
  wire reset_flag_r;
  e603_gnrl_dffrs #(1) reset_flag_dffrs   (1'b0,         reset_flag_r  , clk_aon, rst_core);
  assign hart_under_reset = reset_flag_r;
endmodule
module e603_reset_sync #(
  parameter RST_SYNC_LEVEL = 2
)(
  input  clk,        
  input  rst_n_a,    
  input  reset_bypass,  
  output rst_n_sync
);
  wire rst_n_a_sync;
  e603_gnrl_sync #(.DW(1), .DP(RST_SYNC_LEVEL))
  U_sync (.clk(clk), .rst_n(rst_n_a), .din_a(1'b1), .dout(rst_n_a_sync));
`ifndef SYNTHESIS
  assign rst_n_sync = reset_bypass ? rst_n_a : rst_n_a_sync;
`else
  e603_hand_mux_bit u_sync_rst_sel ( .D0(rst_n_a_sync), .D1(rst_n_a), .S(reset_bypass), .X(rst_n_sync) );
`endif
endmodule
module e603_gnrl_sync # (
  parameter DP = 2,
  parameter DW = 32,
  parameter [DW-1:0] RST_VAL = {DW{1'b0}}
) (
  input  [DW-1:0] din_a,
  output [DW-1:0] dout,
  input           rst_n,
  input           clk
);
`ifdef SYNTHESIS
e603_gnrl_tech_sync #(
  .DP      (DP),
  .DW      (DW),
  .RST_VAL (RST_VAL)
) u_sync (
  .din_a (din_a  ),
  .dout  (dout   ),
  .rst_n (rst_n  ),
  .clk   (clk    )
);
`else
  wire [DW-1:0] sync_dat [DP-1:0];
  genvar i;
  
  
  generate
  for(i=0;i<DP;i=i+1) begin:gen_sync
    if(i==0) begin:gen_i_is_0
      e603_gnrl_dffrs #(DW, RST_VAL) sync_dffrs(din_a,         sync_dat[0], clk, rst_n);
    end
    else begin:gen_i_is_not_0
      e603_gnrl_dffrs #(DW, RST_VAL) sync_dffrs(sync_dat[i-1], sync_dat[i], clk, rst_n);
    end
  end
  endgenerate
  assign dout = sync_dat[DP-1];
`endif
endmodule
module e603_gnrl_dffrs # (
  parameter DW   = 32
, parameter [DW-1:0]  RST  = {DW{1'b1}}
) (
  input      [DW-1:0] dnxt,
  output     [DW-1:0] qout,
  input               clk,
  input               rst_n
);
reg [DW-1:0] qout_r;
always @(posedge clk or negedge rst_n)
begin : DFF_PROC
  if (rst_n == 1'b0)
    qout_r <= RST;
  else
    qout_r <= dnxt;
end
assign qout = qout_r[DW-1:0];
endmodule
