end
assign qout = qout_r[DW-1:0];
endmodule
module e603_gnrl_cdc_rx
# (
  parameter READY_THROUGH = 0,
  parameter DW = 32,
  parameter SYNC_DP = 2
) (
  
  
  
  
  
  
  input  i_vld_a, 
  output i_rdy, 
  input  [DW-1:0] i_dat,
  
  
  output o_vld, 
  input  o_rdy, 
  output [DW-1:0] o_dat,
  input  clk,
  input  rst_n 
);
wire i_vld_sync;
e603_gnrl_sync #(.DP(SYNC_DP), .DW(1)) u_i_vld_sync (
     .clk   (clk),
     .rst_n (rst_n),
     .din_a (i_vld_a),
     .dout  (i_vld_sync)
    );
wire i_vld_sync_r;
e603_gnrl_dffr #(1) i_vld_sync_dffr(i_vld_sync, i_vld_sync_r, clk, rst_n);
wire i_vld_sync_nedge = (~i_vld_sync) & i_vld_sync_r;
wire buf_rdy;
wire i_rdy_r;
wire buf_dat_ena;
wire i_rdy_set;
generate
  if(READY_THROUGH == 0) begin: no_ready_through_gen
    assign i_rdy_set = buf_rdy & i_vld_sync 
                 & (~i_rdy_r)
                 ;
    assign buf_dat_ena = i_rdy_set;
  end
  else begin: ready_through_gen
    assign i_rdy_set = i_vld_sync 
               & o_vld & o_rdy
               ;
    assign buf_dat_ena = (~i_rdy_r) & buf_rdy & i_vld_sync;
  end
endgenerate
wire i_rdy_clr = i_vld_sync_nedge;
wire i_rdy_ena = i_rdy_set |   i_rdy_clr;
wire i_rdy_nxt = i_rdy_set | (~i_rdy_clr);
e603_gnrl_dfflr #(1) i_rdy_dfflr(i_rdy_ena, i_rdy_nxt, i_rdy_r, clk, rst_n);
assign i_rdy = i_rdy_r;
wire buf_vld_r;
wire [DW-1:0] buf_dat_r;
e603_gnrl_dfflr #(DW) buf_dat_dfflr(buf_dat_ena, i_dat, buf_dat_r, clk, rst_n);
wire buf_vld_set = buf_dat_ena;
wire buf_vld_clr = o_vld & o_rdy;
wire buf_vld_ena = buf_vld_set | buf_vld_clr;
wire buf_vld_nxt = buf_vld_set | (~buf_vld_clr);
e603_gnrl_dfflr #(1) buf_vld_dfflr(buf_vld_ena, buf_vld_nxt, buf_vld_r, clk, rst_n);
assign buf_rdy = (~buf_vld_r);
assign o_vld = buf_vld_r;
assign o_dat = buf_dat_r;
endmodule
module e603_gnrl_dfflr # (
  parameter DW   = 32
) (
  input               lden,
  input      [DW-1:0] dnxt,
  output     [DW-1:0] qout,
  input               clk,
  input               rst_n
);
reg [DW-1:0] qout_r;
always @(posedge clk or negedge rst_n)
begin : DFF_PROC
  if (rst_n == 1'b0)
    qout_r <= {DW{1'b0}};
  else if (lden == 1'b1)
    qout_r <= dnxt;
end
assign qout = qout_r[DW-1:0];
