module e603_clkgate (
  input   clk_in,
  input   clkgate_bypass,
  input   clock_en,
  output  clk_out
);
`ifdef SYNTHESIS
e603_gnrl_tech_clkgate u_cg(
    .clk_in             (clk_in             ),
    .clkgate_bypass     (clkgate_bypass     ),
    .clock_en           (clock_en           ),
    .clk_out            (clk_out            )
);
`else
reg enb;
always@(*)
  if (!clk_in)
    enb <= (clock_en | clkgate_bypass);
  `ifdef FPGA_SOURCE
      
      assign clk_out = clk_in;
  `else
    assign clk_out = enb & clk_in;
  `endif
`endif
endmodule
module e603_gnrl_dffl # (
  parameter DW   = 32
) (
  input               lden,
  input      [DW-1:0] dnxt,
  output     [DW-1:0] qout,
  input               clk,
  input               rst_n
);
reg [DW-1:0] qout_r;
always @(posedge clk or negedge rst_n)
begin : DFF_PROC
  if (rst_n == 1'b0)
    qout_r <= {DW{1'b0}};
  else if (lden == 1'b1)
    qout_r <= dnxt;
end
assign qout = qout_r[DW-1:0];
