assign req2_nx = ~req2_clr & (req2 | req2_set);
assign ack1_set = req1 & (dbg_sleep | ack2);
assign ack1_clr = ~req1;
assign req2_set = req1 & (~dbg_sleep) & (~ack1);
assign req2_clr = dbg_sleep | ack2;
