assign dmstatus_sleep[12]    = 1'b1;
assign dmstatus_sleep[11]    = 1'b0;
assign dmstatus_sleep[10]    = 1'b0;
assign dmstatus_sleep[9]     = 1'b0;
assign dmstatus_sleep[8]     = 1'b0;
assign dmstatus_sleep[7]     = 1'b1;
assign dmstatus_sleep[6]     = 1'b0;
assign dmstatus_sleep[5]     = 1'b1;
assign dmstatus_sleep[4]     = 1'b0;
