module e603_dmi # (
    parameter DMI_DATA_BITS  = 32,
    parameter DMI_ADDR_BITS  = 7,
    parameter DMI_OP_BITS    = 2,
    parameter DMI_REG_BITS   = 41
  ) (
input                      dmi_rst_n,
output  [31:0]             dmi2tap_rdata,
output                     dmi2tap_ack,
input                      tap2dmi_req,
input   [DMI_REG_BITS-1:0] tap2dmi_data,
input                      dmi_clk,
output                     dmi_icb_cmd_sel,      
output                     dmi_icb_cmd_valid,      
input                      dmi_icb_cmd_ready,      
output  [31:0]             dmi_icb_cmd_addr,     
output  [31:0]             dmi_icb_cmd_wdata,    
output                     dmi_icb_cmd_read,   
input                      dmi_icb_rsp_valid,    
output                     dmi_icb_rsp_ready, 
input   [31:0]             dmi_icb_rsp_rdata   
);
localparam   DMI_OP_NOP          = 2'b00;
localparam   DMI_OP_READ         = 2'b01;
localparam   DMI_OP_WRITE        = 2'b10;
localparam   DMI_OP_RSV          = 2'b11;
wire	dmi_trans_req;  
wire	dmi_trans_proc; 
wire [DMI_REG_BITS-1:0]	dmi_data;
wire	dmi2tap_ack_set;
wire	dmi2tap_ack_clr;
wire	[DMI_ADDR_BITS-1:0]	dmi_access_addr;
assign  dmi_trans_req     = ~dmi_trans_proc & tap2dmi_req;
assign	dmi_access_addr	  = dmi_data[DMI_REG_BITS-1:(DMI_DATA_BITS+DMI_OP_BITS)];
assign	dmi_icb_cmd_addr  = {{(30-DMI_ADDR_BITS){1'b0}}, dmi_access_addr, 2'b0};
assign	dmi_icb_cmd_read  = ~(dmi_data[DMI_OP_BITS-1:0] == DMI_OP_WRITE);
assign	dmi_icb_cmd_wdata = dmi_data[(DMI_DATA_BITS+DMI_OP_BITS)-1:DMI_OP_BITS];
assign	dmi_icb_cmd_sel   = dmi_icb_cmd_valid;
wire    dmi_trans_proc_set = dmi_trans_req;
wire    dmi_trans_proc_clr = dmi2tap_ack_clr;
wire    dmi_trans_proc_ena = dmi_trans_proc_set | dmi_trans_proc_clr;
wire    dmi_trans_proc_nxt = ~dmi_trans_proc_clr;
e603_gnrl_dfflr #(1) dmi_trans_proc_dfflr (dmi_trans_proc_ena, dmi_trans_proc_nxt, dmi_trans_proc, dmi_clk, dmi_rst_n);
wire    dmi_icb_cmd_valid_set = dmi_trans_proc_set;
wire    dmi_icb_cmd_hsked = dmi_icb_cmd_valid & dmi_icb_cmd_ready;
wire    dmi_icb_cmd_valid_clr = dmi_icb_cmd_hsked;
wire    dmi_icb_cmd_valid_ena = dmi_icb_cmd_valid_set | dmi_icb_cmd_valid_clr;
wire    dmi_icb_cmd_valid_nxt = ~dmi_icb_cmd_valid_clr;
e603_gnrl_dfflr #(1) dmi_icb_cmd_valid_dfflr (dmi_icb_cmd_valid_ena, dmi_icb_cmd_valid_nxt, dmi_icb_cmd_valid, dmi_clk, dmi_rst_n);
assign  dmi_icb_rsp_ready = 1'b1;
wire	dmi_data_ena;
assign	dmi_data_ena = dmi_trans_req;
// spyglass disable_block Ac_datahold01a
// SMD: Data-enable sequencing check: Partially-Proved
// SJ:  it is okay 
e603_gnrl_dfflr #(DMI_REG_BITS)    dmi_data_dfflr  (dmi_data_ena, tap2dmi_data, dmi_data, dmi_clk, dmi_rst_n);
// spyglass enable_block Ac_datahold01a
assign  dmi2tap_rdata = dmi_icb_rsp_rdata;
wire	dmi2tap_ack_ena;
wire	dmi2tap_ack_nxt;
wire    dmi_icb_rsp_hsked = dmi_icb_rsp_valid & dmi_icb_rsp_ready;
assign	dmi2tap_ack_set = dmi_icb_rsp_hsked;
assign	dmi2tap_ack_clr = ~tap2dmi_req;
assign	dmi2tap_ack_ena = dmi2tap_ack_set | dmi2tap_ack_clr;
assign	dmi2tap_ack_nxt = dmi2tap_ack_set & ~dmi2tap_ack_clr;
e603_gnrl_dfflr #(1)    dmi2tap_ack_dfflr  (dmi2tap_ack_ena, dmi2tap_ack_nxt, dmi2tap_ack, dmi_clk, dmi_rst_n);
endmodule
