wire rx_evt_r;
wire rx_evt_set = rx_evt;
wire rx_evt_clr = rx_evt_ack_r;
wire rx_evt_ena = rx_evt_set | rx_evt_clr;
wire rx_evt_nxt = rx_evt_set | (~rx_evt_clr);
e603_gnrl_dfflr #(1) rx_evt_dfflr (rx_evt_ena, rx_evt_nxt , rx_evt_r,  clk_aon, rst_n);
assign rx_evt_req = rx_evt_r;
wire nmi_irq_d1;
e603_gnrl_dffr #(1) nmi_irq_d_dffr(nmi_irq, nmi_irq_d1, clk_aon, rst_n);
wire nmi_irq_set = nmi_irq & (~nmi_irq_d1);
wire nmi_irq_clr = nmi_irq_taken_r;
wire nmi_irq_ena = nmi_irq_set | nmi_irq_clr; 
wire nmi_irq_nxt = nmi_irq_set | (~nmi_irq_clr); 
e603_gnrl_dfflr #(1) nmi_irq_dfflr(nmi_irq_ena, nmi_irq_nxt, nmi_irq_r, clk_aon, rst_n);
endmodule
module e603_clk_ctrl (
  input  clk_aon,    
  input  clk,        
  input  rst_n,      
  input  clkgate_bypass,  
  
  
      
  input  core_cgstop,
  input  lockstep_en,
  input  tmr_active,
  output clk_tmr,
  input  clic_active,
  output clk_clic,
  input  plic_active,
  output clk_plic,
  input  fpu_active,
  input  fpu_mac_active,
  input  fpu_div_active,
  input  fpu_mis_active,
  input  fpu_rf_active,
  output clk_fpu,
  output clk_fpu_mac,
  output clk_fpu_div,
  output clk_fpu_mis,
  output clk_fpu_rf,
  input  pft_active,
  output clk_pft,
  input  icache_active,
  output clk_icache,
  output icache_ls,
  input  dcache_active,
  output clk_dcache,
  input  mmu_active,
  output clk_mmu,
  input  ifu_active,
  input  exu_active,
  input  lsu_active,
  input  biu_active,
  input  exu_rf_active,
  input  lbiu_active,
    
  output clk_ifu,
  output clk_exu,
  output clk_lsu,
  output clk_exu_rf,
  output clk_lbiu, 
    
  output clk_biu 
);
  
  
      
      
      
  wire fpu_clk_en     = core_cgstop | (fpu_active   & lockstep_en  );
  wire fpu_mac_clk_en = core_cgstop | (fpu_mac_active & lockstep_en);
  wire fpu_div_clk_en = core_cgstop | (fpu_div_active & lockstep_en);
  wire fpu_mis_clk_en = core_cgstop | (fpu_mis_active & lockstep_en);
  wire fpu_rf_clk_en  = core_cgstop | (fpu_rf_active & lockstep_en);
  wire ifu_clk_en = core_cgstop | (ifu_active & lockstep_en);
      
      
      
      
  wire exu_clk_en = core_cgstop | (exu_active & lockstep_en);
  wire lsu_clk_en = core_cgstop | (lsu_active & lockstep_en);
  wire biu_clk_en = core_cgstop | (biu_active & lockstep_en);
  wire exu_rf_clk_en = core_cgstop | (exu_rf_active & lockstep_en);
  wire lbiu_clk_en = core_cgstop | (lbiu_active & lockstep_en);
  
  e603_clkgate u_clic_clkgate(
    .clk_in   (clk_aon    ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (clic_active),
    .clk_out  (clk_clic)
  );
  
  e603_clkgate u_plic_clkgate(
    .clk_in   (clk_aon    ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (plic_active),
    .clk_out  (clk_plic)
  );
  
  e603_clkgate u_tmr_clkgate(
    .clk_in   (clk_aon    ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (tmr_active),
    .clk_out  (clk_tmr)
  );
  e603_clkgate u_fpu_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (fpu_clk_en),
    .clk_out  (clk_fpu)
  );
  e603_clkgate u_fpu_mac_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (fpu_mac_clk_en),
    .clk_out  (clk_fpu_mac)
  );
  e603_clkgate u_fpu_div_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (fpu_div_clk_en),
    .clk_out  (clk_fpu_div)
  );
  e603_clkgate u_fpu_mis_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (fpu_mis_clk_en),
    .clk_out  (clk_fpu_mis)
  );
  e603_clkgate u_fpu_rf_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (fpu_rf_clk_en),
    .clk_out  (clk_fpu_rf)
  );
  e603_clkgate u_ifu_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (ifu_clk_en),
    .clk_out  (clk_ifu)
  );
  e603_clkgate u_exu_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (exu_clk_en),
    .clk_out  (clk_exu)
  );
  e603_clkgate u_exu_rf_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (exu_rf_clk_en),
    .clk_out  (clk_exu_rf)
  );
  e603_clkgate u_lsu_clkgate(
    .clk_in   (clk_aon        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (lsu_clk_en),
    .clk_out  (clk_lsu)
  );
  e603_clkgate u_biu_clkgate(
    .clk_in   (clk_aon        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (biu_clk_en),
    .clk_out  (clk_biu)
  );
  e603_clkgate u_lbiu_clkgate(
    .clk_in   (clk_aon        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (lbiu_clk_en),
    .clk_out  (clk_lbiu)
  );
      
      
      
  wire icache_clk_en = core_cgstop | (icache_active & lockstep_en);
  assign icache_ls = ~icache_clk_en;
  e603_clkgate u_icache_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (icache_clk_en),
    .clk_out  (clk_icache)
  );
       
      
      
  wire dcache_clk_en = core_cgstop | (dcache_active & lockstep_en);
  wire dcache_ls = ~dcache_clk_en;
  e603_clkgate u_dcache_clkgate(
    .clk_in   (clk_aon        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (dcache_clk_en),
    .clk_out  (clk_dcache)
  );
      
      
      
  wire mmu_clk_en = core_cgstop | (mmu_active & lockstep_en);
  e603_clkgate u_mmu_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (mmu_clk_en),
    .clk_out  (clk_mmu)
  );
      
      
      
  wire pft_clk_en = core_cgstop | (pft_active & lockstep_en);
  e603_clkgate u_pft_clkgate(
    .clk_in   (clk        ),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (pft_clk_en),
    .clk_out  (clk_pft)
  );
endmodule
module e603_dbg_csr (
    
  input csr_ena,
  input csr_wr_en,
  input csr_rd_en,
  input [12-1:0] csr_idx,
  input wbck_csr_wen,
  input  [64-1:0] wbck_csr_dat,
  output [64-1:0] read_csr_dat,
  output csr_addr_legal,
  output csr_prv_ilgl,
    
  input  [64-1:0] cmt_dpc,
  input  cmt_dpc_ena,
  input  [3-1:0] cmt_dcause,
  input  cmt_dcause_ena,
  input  cmt_dbg_mprven_ena,
  input  cmt_dprv_ena,
  input  [2-1:0] cmt_dprv,
  output [2-1:0] dbg_prv_r,
    
  output [64*2-1:0] dbg_tdata1,
  output [64*2-1:0] dbg_tdata2,
  input  icount_taken_ena,
  output[64-1:0]  csr_dpc_r,
  output dbg_mode,
  output dbg_step_r,
  output dbg_ebreakm_r,
  output dbg_ebreaks_r,
  output dbg_stopcount,
  output dbg_stoptime,
  output dbg_ebreaku_r,
  output dbg_stepie,
  output dbg_mprven,
  input  nmi_irq_r,
  input  clk,
  input  rst_n
  );
localparam TRIGM_NUM_LOG2 =(2<=2)?1:(2<=4)?2:(2<=8)?3:(2<=16)?4:(2<=32)?5:(2<=64)?6:(2<=128)?7:(2<=256)?8:(2<=512)?9:(2<=1024)?10:(2<=2048)?11:(2<=4096)?12:-1;
wire [64-1:0] dcsr_r;
wire [64-1:0] dpc_r;//__KEEP_SIGNAL__
wire [64-1:0] dscratch0_r;
wire sel_dcsr_raw      = (csr_idx == 12'h7b0);
wire sel_dpc_raw       = (csr_idx == 12'h7b1);
wire sel_dscratch0_raw = (csr_idx == 12'h7b2);
wire [64-1:0] dscratch1_r;
wire sel_dscratch1_raw = (csr_idx == 12'h7b3);
wire sel_dscratch1 = dbg_mode & sel_dscratch1_raw;
wire rd_dscratch1 = csr_rd_en & sel_dscratch1;
wire sel_dcsr      = dbg_mode & sel_dcsr_raw     ;
wire sel_dpc       = dbg_mode & sel_dpc_raw      ;
wire sel_dscratch0 = dbg_mode & sel_dscratch0_raw;
assign csr_prv_ilgl = (~dbg_mode) & ( 
              sel_dcsr_raw      
            | sel_dpc_raw       
            | sel_dscratch0_raw 
            | sel_dscratch1_raw 
            );
wire rd_dcsr     = csr_rd_en & sel_dcsr    ;
wire rd_dpc      = csr_rd_en & sel_dpc     ;
wire rd_dscratch0 = csr_rd_en & sel_dscratch0;
wire sel_tselect  = (csr_idx == 12'h7a0);
wire sel_tdata1   = (csr_idx == 12'h7a1);
wire sel_tdata2   = (csr_idx == 12'h7a2);
wire sel_tdata3   = (csr_idx == 12'h7a3);
wire sel_tinfo    = (csr_idx == 12'h7a4);
wire sel_tcontrol = (csr_idx == 12'h7a5);  
wire sel_mcontext = (csr_idx == 12'h7a8);
wire sel_textra32 = (csr_idx == 12'h7a3);
wire sel_scontext = (csr_idx == 12'h7aa);
wire rd_tselect  =  csr_rd_en & sel_tselect ;
wire rd_tdata1   =  csr_rd_en & sel_tdata1  ;
wire rd_tdata2   =  csr_rd_en & sel_tdata2  ;
wire rd_tdata3   =  csr_rd_en & sel_tdata3  ;
wire rd_tinfo    =  csr_rd_en & sel_tinfo   ;
wire rd_tcontrol =  csr_rd_en & sel_tcontrol;
wire rd_mcontext =  csr_rd_en & sel_mcontext;
wire rd_textra32 =  csr_rd_en & sel_textra32;
wire rd_scontext =  csr_rd_en & sel_scontext;
wire wr_tselect_ena  = wbck_csr_wen & sel_tselect ;
wire wr_tdata1_ena   = wbck_csr_wen & sel_tdata1  ;
wire wr_tdata2_ena   = wbck_csr_wen & sel_tdata2  ;
wire [64-1:0] tdata1_r ;
wire [64-1:0] tdata2_r ;
wire [64-1:0] tselect_r ;
wire [64-1:0] csr_tdata1   = tdata1_r ;
wire [64-1:0] csr_tdata2   = tdata2_r ;
wire [64-1:0] csr_tdata3   = 64'b0 ;
   
   
   
wire [64-1:0] csr_tinfo    = {{64-6{1'b0}},4'b1111,2'b0};
wire [64-1:0] csr_tselect  = tselect_r ;
wire wr_dcsr_ena     = wbck_csr_wen & sel_dcsr    ;
wire wr_dpc_ena      = wbck_csr_wen & sel_dpc     ;
wire wr_dscratch0_ena = wbck_csr_wen & sel_dscratch0;
wire wr_dscratch1_ena = wbck_csr_wen & sel_dscratch1;
wire [64-1:0] csr_dcsr     = dcsr_r    ;
wire [64-1:0] csr_dpc      = dpc_r     ;
wire [64-1:0] csr_dscratch0 = dscratch0_r;
wire [64-1:0] csr_dscratch1 = dscratch1_r;
assign {csr_addr_legal, read_csr_dat} = {1'b0,64'b0} 
               | {sel_dcsr_raw    ,({64{rd_dcsr       }} & csr_dcsr    )      }
               | {sel_dpc_raw     ,({64{rd_dpc        }} & csr_dpc     )      }
               | {sel_dscratch0_raw,({64{rd_dscratch0   }} & csr_dscratch0)      }
               | {sel_dscratch1_raw,({64{rd_dscratch1   }} & csr_dscratch1)      }
               | {sel_tselect, ({64{rd_tselect    }} & csr_tselect)       }
               | {sel_tdata1 , ({64{rd_tdata1     }} & csr_tdata1)        }
               | {sel_tdata2 , ({64{rd_tdata2     }} & csr_tdata2)        }
               | {sel_tdata3 , ({64{rd_tdata3     }} & csr_tdata3)        }
               | {sel_tinfo  , ({64{rd_tinfo      }} & csr_tinfo )        }
               | {sel_tcontrol  , ({64{rd_tcontrol}} & {64{1'b0}} )        }
               | {sel_mcontext  , ({64{rd_mcontext}} & {64{1'b0}} )        }
               | {sel_textra32  , ({64{rd_textra32}} & {64{1'b0}} )        }
               | {sel_scontext  , ({64{rd_scontext}} & {64{1'b0}} )      }
               ;
assign csr_dpc_r = dpc_r;
  wire dpc_ena;//__KEEP_SIGNAL__
  wire [64-1:0] dpc_nxt;//__KEEP_SIGNAL__
  assign dpc_ena = wr_dpc_ena | cmt_dpc_ena;
  assign dpc_nxt[64-1:1] = 
       cmt_dpc_ena ? cmt_dpc[64-1:1] 
                   : wbck_csr_dat[64-1:1];
  assign dpc_nxt[0] = 1'b0; 
  e603_gnrl_dfflr #(64) dpc_dfflr (dpc_ena, dpc_nxt, dpc_r, clk, rst_n);
  
  wire dscratch0_ena = wr_dscratch0_ena;
  wire [64-1:0] dscratch0_nxt;
  assign dscratch0_nxt = wbck_csr_dat;
  e603_gnrl_dfflr #(64) dscratch0_dfflr (dscratch0_ena, dscratch0_nxt, dscratch0_r, clk, rst_n);
 
  wire dscratch1_ena = wr_dscratch1_ena;
  wire [64-1:0] dscratch1_nxt;
  assign dscratch1_nxt = wbck_csr_dat;
  e603_gnrl_dfflr #(64) dscratch1_dfflr (dscratch1_ena, dscratch1_nxt, dscratch1_r, clk, rst_n);
 
// spyglass disable_block BitOrder-ML
// SMD: the vector size,word size,and memory size specifications are in the [MSB:LSB] format
// SJ:  bit-order is not cared
  wire[64-1:0] tdata1 [0:2-1];
  wire[64-1:0] tdata2 [0:2-1];
  wire[2-1:0] tdata1_wr_ena;
  wire[2-1:0] tdata2_wr_ena;
  wire[2-1:0] tselect_sel;
  wire[2-1:0] tdata_wr_enable;
  wire[2-1:0] tdata1_type_ena;
  wire[4-1:0] tdata1_type_nxt[0:2-1];
  wire[4-1:0] tdata1_type    [0:2-1];
  wire[2-1:0] tdata1_type_2;
  wire[2-1:0] tdata1_type_3;
  wire[2-1:0] tdata1_type_4;
  wire[2-1:0] tdata1_type_5;
  wire[2-1:0] tdata1_type_nxt_2;
  wire[2-1:0] tdata1_type_nxt_3;
  wire[2-1:0] tdata1_type_nxt_4;
  wire[2-1:0] tdata1_type_nxt_5;
  wire[2-1:0] tdata1_dmode_ena;
  wire[1-1:0] tdata1_dmode_nxt[0:2-1];
  wire[1-1:0] tdata1_dmode    [0:2-1];
  wire[2-1:0] tdata1_data_ena;
  wire[59-1:0] tdata1_data_nxt[0:2-1];
  wire[59-1:0] tdata1_data    [0:2-1];
  wire[59-1:0] tdata1_data_pos    [0:2-1];
  wire[2-1:0] tdata1_data_9_6_clr;
  wire[2-1:0] tdata1_data_9_6_ena;
  wire[3:0] tdata1_data_9_6_nxt[0:2-1];
// spyglass enable_block BitOrder-ML
  wire tselect_ena = wr_tselect_ena;
  wire [TRIGM_NUM_LOG2-1:0] tselect_nxt = wbck_csr_dat[TRIGM_NUM_LOG2-1:0];
  e603_gnrl_dfflr #(TRIGM_NUM_LOG2) tselect_dfflr (tselect_ena, tselect_nxt, tselect_r[TRIGM_NUM_LOG2-1:0], clk, rst_n);
  assign tselect_r[64-1:TRIGM_NUM_LOG2] = {64-1-TRIGM_NUM_LOG2{1'b0}};
  genvar i;
  generate 
  for(i=0; i<2; i=i+1) begin: gen_tdata 
    assign dbg_tdata2 [64*i +: 64] = tdata2[i];
    assign dbg_tdata1 [64*i +: 64] = tdata1[i];
    assign tselect_sel[i] = (tselect_r[TRIGM_NUM_LOG2-1:0] == i[TRIGM_NUM_LOG2-1:0]);
    
    
    
    
    assign tdata_wr_enable[i] = (tdata1_dmode[i] ? dbg_mode : 1'b1);
    assign tdata1_wr_ena[i] = wr_tdata1_ena & tselect_sel[i] & tdata_wr_enable[i];
    assign tdata2_wr_ena[i] = wr_tdata2_ena & tselect_sel[i] & tdata_wr_enable[i];
    
    e603_gnrl_dfflr #(64) tdata2_dfflr (tdata2_wr_ena[i], wbck_csr_dat, tdata2[i], clk, rst_n);
    
    assign tdata1_type_ena[i] = tdata1_wr_ena[i];
                               
    assign tdata1_type_nxt[i] = 
                              (wbck_csr_dat[64-1:64-4] == 4'd5) ? 4'd5 :
                              (wbck_csr_dat[64-1:64-4] == 4'd4) ? 4'd4 :
                              (wbck_csr_dat[64-1:64-4] == 4'd3) ? 4'd3 :
                                                                                          4'd2 ;
    e603_gnrl_dfflr #(2) tdata1_type_3_2_dfflr (tdata1_type_ena[i], tdata1_type_nxt[i][3:2], tdata1_type[i][3:2], clk, rst_n);
    e603_gnrl_dfflrs#(1) tdata1_type_1_dfflrs  (tdata1_type_ena[i], tdata1_type_nxt[i][1]  , tdata1_type[i][1]  , clk, rst_n);
    e603_gnrl_dfflr #(1) tdata1_type_0_dfflr   (tdata1_type_ena[i], tdata1_type_nxt[i][0]  , tdata1_type[i][0]  , clk, rst_n);
    assign tdata1_type_nxt_2[i] = (tdata1_type_nxt[i] == 4'd2);
    assign tdata1_type_nxt_3[i] = (tdata1_type_nxt[i] == 4'd3);
    assign tdata1_type_nxt_4[i] = (tdata1_type_nxt[i] == 4'd4);
    assign tdata1_type_nxt_5[i] = (tdata1_type_nxt[i] == 4'd5);
    assign tdata1_type_2[i] = (tdata1_type[i] == 4'd2);
    assign tdata1_type_3[i] = (tdata1_type[i] == 4'd3);
    assign tdata1_type_4[i] = (tdata1_type[i] == 4'd4);
    assign tdata1_type_5[i] = (tdata1_type[i] == 4'd5);
    
    assign tdata1_dmode_ena[i] = tdata1_wr_ena[i] & dbg_mode;
    assign tdata1_dmode_nxt[i] = wbck_csr_dat[59];
    e603_gnrl_dfflr #(1) tdata1_dmode_dfflr (tdata1_dmode_ena[i], tdata1_dmode_nxt[i], tdata1_dmode[i], clk, rst_n);
    
    assign tdata1_data_ena[i] = tdata1_wr_ena[i];
    assign tdata1_data_nxt[i] = wbck_csr_dat[64-6:0] & (
            
        ({59{tdata1_type_nxt_2[i]}} & {6'd12,{64-29{1'b0}},
                                                             (
                              
                              
                                                                (wbck_csr_dat[17:12] == 6'd1) ? 6'd1 : 6'd0
                                                             ),
                              
                                                             1'b0,
                                                             (
                              
                                                                (wbck_csr_dat[10:7] == 4'd0) ? 4'd0 :
                                                                (wbck_csr_dat[10:7] == 4'd1) ? 4'd1 : 4'd0
                                                                
                                                             ),
                                                               wbck_csr_dat[6],1'b0,wbck_csr_dat[4:0]})
      | ({59{tdata1_type_nxt_3[i]}} & {16'b0,1'b1,wbck_csr_dat[9],1'b0,wbck_csr_dat[7:6],
                                                                ((wbck_csr_dat[5:0] == 6'd1) ? 6'd1 : 6'd0)
                                                       })
      | ({59{tdata1_type_nxt_4[i]}} & {17'b0,wbck_csr_dat[9],1'b0,wbck_csr_dat[7:6],
                                                                ((wbck_csr_dat[5:0] == 6'd1) ? 6'd1 : 6'd0)
                                                       })
      | ({59{tdata1_type_nxt_5[i]}} & {17'b0,wbck_csr_dat[9],1'b0,wbck_csr_dat[7:6],
                                                                ((wbck_csr_dat[5:0] == 6'd1) ? 6'd1 : 6'd0)
                                                       })
      );
    e603_gnrl_dfflr #(17) tdata1_data_26_10dfflr (tdata1_data_ena[i], tdata1_data_nxt[i][26:10], tdata1_data[i][26:10], clk, rst_n);
