module e603_fpu_stage_dffl #(
    parameter DW = 1,
    parameter STAGE_EN = 0
)(
  input               lden, 
  input      [DW-1:0] dnxt,
  output     [DW-1:0] qout,
  input               clk ,
  input               rst_n
);
genvar i;
generate 
if(STAGE_EN==1) begin:gen_fpu_stage_dffl
reg [DW-1:0] qout_r;
always @(posedge clk or negedge rst_n)
begin : DFFLR_PROC
  if (rst_n == 1'b0)
    qout_r <= {DW{1'b0}};
  else if (lden == 1'b1)
    qout_r <= dnxt;
end
assign qout = qout_r;
end
else begin:gen_fpu_ex_bypass
    assign qout = dnxt;
end
endgenerate
endmodule
