  wire sdb_alc_rs2_fwd_e5 = ((sdb_i_rs2_dep_itag == exu2lsu_fwd_itag_e5) & exu2lsu_fwd_itag_vld_e5 & exu2lsu_fwd_res_vld_e5);
  wire sdb_alc_rs2_fwd_p0 = ((sdb_i_rs2_dep_itag == exu2lsu_fwd_itag_p0) & exu2lsu_fwd_itag_vld_p0 & exu2lsu_fwd_res_vld_p0);
  wire sdb_alc_rs2_dep_en = sdb_i_rs2_dep_en & ~(sdb_alc_rs2_fwd_e5 | sdb_alc_rs2_fwd_p0) & ~sdb_i_flush_flag; 
  wire [64-1:0] sdb_alc_rs2_fwd_wdata =  64'b0
                                                  | ({64{sdb_alc_rs2_fwd_e5}} & {{64-64{1'b0}},exu2lsu_fwd_res_e5})
                                                  | ({64{sdb_alc_rs2_fwd_p0}} & {{64-64{1'b0}},exu2lsu_fwd_res_p0})
                                                  ;
  wire [64-1:0] sdb_alc_wdata_real = sdb_i_rs2_dep_en ? sdb_alc_rs2_fwd_wdata : sdb_i_wdata; 
  
  wire sdb_rs2_ent0_fwd_e5 = ((sdb_rs2_dep_itag_ent0_r == exu2lsu_fwd_itag_e5) & exu2lsu_fwd_itag_vld_e5 & exu2lsu_fwd_res_vld_e5);
  wire sdb_rs2_ent0_fwd_p0 = ((sdb_rs2_dep_itag_ent0_r == exu2lsu_fwd_itag_p0) & exu2lsu_fwd_itag_vld_p0 & exu2lsu_fwd_res_vld_p0);
  wire sdb_rs2_dep_en_ent0_fwd_ena = sdb_rs2_dep_en_ent0_r & (sdb_rs2_ent0_fwd_e5 | sdb_rs2_ent0_fwd_p0);
  wire [64-1:0] sdb_rs2_ent0_fwd_wdata =  64'b0
                                                  | ({64{sdb_rs2_ent0_fwd_e5}} & {{64-64{1'b0}},exu2lsu_fwd_res_e5})
                                                  | ({64{sdb_rs2_ent0_fwd_p0}} & {{64-64{1'b0}},exu2lsu_fwd_res_p0})
                                                  ;
  wire sdb_rs2_ent1_fwd_e5 = ((sdb_rs2_dep_itag_ent1_r == exu2lsu_fwd_itag_e5) & exu2lsu_fwd_itag_vld_e5 & exu2lsu_fwd_res_vld_e5);
  wire sdb_rs2_ent1_fwd_p0 = ((sdb_rs2_dep_itag_ent1_r == exu2lsu_fwd_itag_p0) & exu2lsu_fwd_itag_vld_p0 & exu2lsu_fwd_res_vld_p0);
  wire sdb_rs2_dep_en_ent1_fwd_ena = sdb_rs2_dep_en_ent1_r & (sdb_rs2_ent1_fwd_e5 | sdb_rs2_ent1_fwd_p0);
  wire [64-1:0] sdb_rs2_ent1_fwd_wdata =  64'b0
                                                  | ({64{sdb_rs2_ent1_fwd_e5}} & {{64-64{1'b0}},exu2lsu_fwd_res_e5})
                                                  | ({64{sdb_rs2_ent1_fwd_p0}} & {{64-64{1'b0}},exu2lsu_fwd_res_p0})
                                                  ;
  
  
  wire sdb_rs2_dep_en_ent0_nxt;
  wire sdb_rs2_dep_en_ent0_ena;
  assign sdb_rs2_dep_en_ent0_ena =   sdb_ent0_pack_ena
                                      | sdb_rs2_dep_en_ent0_fwd_ena
                                      ;
  assign sdb_rs2_dep_en_ent0_nxt =  (sdb_alc_vec_ena[0] & sdb_alc_rs2_dep_en);
                                     
  e603_gnrl_dfflr #(1) sdb_rs2_dep_en_ent0_dfflr (sdb_rs2_dep_en_ent0_ena, sdb_rs2_dep_en_ent0_nxt , sdb_rs2_dep_en_ent0_r, clk, rst_n);
  wire [4-1:0] sdb_rs2_dep_itag_ent0_nxt;
  wire sdb_rs2_dep_itag_ent0_ena;
  assign sdb_rs2_dep_itag_ent0_ena =  sdb_ent0_pack_ena;
  assign sdb_rs2_dep_itag_ent0_nxt =  sdb_i_rs2_dep_itag;
  e603_gnrl_dfflr #(4) sdb_rs2_dep_itag_ent0_dfflr (sdb_rs2_dep_itag_ent0_ena, sdb_rs2_dep_itag_ent0_nxt , sdb_rs2_dep_itag_ent0_r, clk, rst_n);
  wire sdb_rs2_dep_alc_ent0_nxt;
  wire sdb_rs2_dep_alc_ent0_ena;
  assign sdb_rs2_dep_alc_ent0_ena =  sdb_ent0_pack_ena;
  assign sdb_rs2_dep_alc_ent0_nxt =  sdb_i_rs2_dep_alc;
  e603_gnrl_dfflr #(1) sdb_rs2_dep_alc_ent0_dfflr (sdb_rs2_dep_alc_ent0_ena, sdb_rs2_dep_alc_ent0_nxt , sdb_rs2_dep_alc_ent0_r, clk, rst_n);
  
  wire [64-1:0] sdb_wdata_ent0_nxt;
  wire                    sdb_wdata_ent0_ena;
  assign sdb_wdata_ent0_ena      =   sdb_ent0_pack_ena
                                      | sdb_rs2_dep_en_ent0_fwd_ena
                                      ;
  assign sdb_wdata_ent0_nxt      = sdb_alc_vec_ena[0] ? sdb_alc_wdata_real :
                                      sdb_rs2_ent0_fwd_wdata;
  e603_gnrl_dfflr #(64) sdb_wdata_ent0_dfflr (sdb_wdata_ent0_ena, sdb_wdata_ent0_nxt , sdb_wdata_ent0_r, clk, rst_n);
  
  wire sdb_rs2_dep_en_ent1_nxt;
  wire sdb_rs2_dep_en_ent1_ena;
  assign sdb_rs2_dep_en_ent1_ena =   sdb_ent1_pack_ena
                                      | sdb_rs2_dep_en_ent1_fwd_ena
                                      ;
  assign sdb_rs2_dep_en_ent1_nxt =  (sdb_alc_vec_ena[1] & sdb_alc_rs2_dep_en);
                                     
  e603_gnrl_dfflr #(1) sdb_rs2_dep_en_ent1_dfflr (sdb_rs2_dep_en_ent1_ena, sdb_rs2_dep_en_ent1_nxt , sdb_rs2_dep_en_ent1_r, clk, rst_n);
  wire [4-1:0] sdb_rs2_dep_itag_ent1_nxt;
  wire sdb_rs2_dep_itag_ent1_ena;
  assign sdb_rs2_dep_itag_ent1_ena =  sdb_ent1_pack_ena;
  assign sdb_rs2_dep_itag_ent1_nxt =  sdb_i_rs2_dep_itag;
  e603_gnrl_dfflr #(4) sdb_rs2_dep_itag_ent1_dfflr (sdb_rs2_dep_itag_ent1_ena, sdb_rs2_dep_itag_ent1_nxt , sdb_rs2_dep_itag_ent1_r, clk, rst_n);
  wire sdb_rs2_dep_alc_ent1_nxt;
  wire sdb_rs2_dep_alc_ent1_ena;
  assign sdb_rs2_dep_alc_ent1_ena =  sdb_ent1_pack_ena;
  assign sdb_rs2_dep_alc_ent1_nxt =  sdb_i_rs2_dep_alc;
  e603_gnrl_dfflr #(1) sdb_rs2_dep_alc_ent1_dfflr (sdb_rs2_dep_alc_ent1_ena, sdb_rs2_dep_alc_ent1_nxt , sdb_rs2_dep_alc_ent1_r, clk, rst_n);
  
  wire [64-1:0] sdb_wdata_ent1_nxt;
  wire                    sdb_wdata_ent1_ena;
  assign sdb_wdata_ent1_ena      =   sdb_ent1_pack_ena
                                      | sdb_rs2_dep_en_ent1_fwd_ena
                                      ;
  assign sdb_wdata_ent1_nxt      = sdb_alc_vec_ena[1] ? sdb_alc_wdata_real :
                                      sdb_rs2_ent1_fwd_wdata;
  e603_gnrl_dfflr #(64) sdb_wdata_ent1_dfflr (sdb_wdata_ent1_ena, sdb_wdata_ent1_nxt , sdb_wdata_ent1_r, clk, rst_n);
  
  
  
  
  
  
  wire [2-1:0] sdb_st_dev_vec = sdb_st_valid_pre_vec & sdb_device_vec; 
                                                                                          
  wire sdb_st_any_dev  = |sdb_st_dev_vec;
  wire sdb_any_dev_ena = sdb_alc_ena | sdb_st_buf_hsked;
                                                                        
  wire sdb_any_dev_nxt = sdb_alc_ena ? sdb_i_device :
                         sdb_st_any_dev;  
  
  e603_gnrl_dfflr #(1) sdb_any_dev_dfflr (sdb_any_dev_ena, sdb_any_dev_nxt , sdb_any_dev, clk, rst_n);
  
  
  
  
  
  wire sdb_any_ld_pre  = |sdb_ld_valid_real_vec;   
  wire sdb_any_ld_ena = sdb_alc_ena | sdb_ld_buf_hsked_pos;
  wire sdb_any_ld_nxt =   (sdb_alc_ena          & (sdb_i_load_flg ? 1'b1 : ~sdb_no_ld & (sdb_ld_buf_hsked_pos ? sdb_any_ld_pre : 1'b1))) 
                        | (sdb_ld_buf_hsked_pos & sdb_any_ld_pre   )    
                        ;
  
  
  wire sdb_no_ld_ena = sdb_any_ld_ena;
  wire sdb_no_ld_nxt = ~sdb_any_ld_nxt;
  e603_gnrl_dfflrs #(1) sdb_no_ld_dfflrs (sdb_no_ld_ena, sdb_no_ld_nxt , sdb_no_ld, clk, rst_n);
  
  
  
  
  assign sdb_o_sel = sdb_i_ld_byp | sdb_not_empty;  
  
  assign sdb_o_valid = sdb_i_ld_byp ? sdb_i_ld_byp_valid : (sdb_ld_buf_valid_pos | sdb_st_buf_valid_pos);
  
  assign sdb_o_fake = 
                      sdb_i_ld_byp        ? (sdb_i_fake | sdb_i_ld_dep) : 
                      1'b0;
  
  wire [67-1:0] o_sdb_pack;
  assign o_sdb_pack = sdb_i_ld_byp         ? sdb_i_pack   :
                      sdb_ld_buf_valid_pos ? sdb_ld_buf_pack :
                      sdb_st_buf_pack;
  
  assign {
       sdb_o_unalgnamo                          ,
     sdb_o_addr                    [  31:   0],
     sdb_o_read                               ,
     sdb_o_lock                               ,
     sdb_o_excl                               ,
     sdb_o_back2agu                           ,
     sdb_o_device                             ,
     sdb_o_nc                                 ,
     sdb_o_mmode                              ,
     sdb_o_smode                              ,
     sdb_o_dmode                              ,
     sdb_o_wmask                   [   7:   0],
     sdb_o_size                    [   1:   0],
     sdb_o_usign                              ,
     sdb_o_itag                    [   3:   0],
     sdb_o_busy                               ,
     sdb_o_flhw                               ,
     sdb_o_fpu_dp                             ,
     sdb_o_fpu_sp                             ,
     sdb_o_flags_fswh              [   4:   0]
}
  = o_sdb_pack[67-2:0];
 
  
  wire [64-1:0] sdb_st_buf_wdata_algn = 
            ({64{sdb_st_buf_size == 2'b00}} & {8{sdb_st_buf_wdata [ 7:0]}})
          | ({64{sdb_st_buf_size == 2'b01}} & {4{sdb_st_buf_wdata [15:0]}})
          | ({64{sdb_st_buf_size == 2'b10}} & {2{sdb_st_buf_wdata [31:0]}})
          | ({64{sdb_st_buf_size == 2'b11}} &    sdb_st_buf_wdata [63:0])
          ; 
  assign sdb_o_wdata = 
                      sdb_st_buf_wdata_algn;
  assign agu_icb_cmd_sel                           = sdb_o_sel                                ;
  assign agu_icb_cmd_fake                          = sdb_o_fake                               ;
  assign agu_icb_cmd_valid                         = sdb_o_valid                              ;
  assign sdb_o_ready                               = agu_icb_cmd_ready                        ;
  assign agu_icb_cmd_addr              [  31:   0] = sdb_o_addr                    [  31:   0];
  assign agu_icb_cmd_read                          = sdb_o_read                               ;
  assign agu_icb_cmd_lock                          = sdb_o_lock                               ;
  assign agu_icb_cmd_excl                          = sdb_o_excl                               ;
  assign agu_icb_cmd_back2agu                      = sdb_o_back2agu                           ;
  assign agu_icb_cmd_device                        = sdb_o_device                             ;
  assign agu_icb_cmd_nc                            = sdb_o_nc                                 ;
  assign agu_icb_cmd_mmode                         = sdb_o_mmode                              ;
  assign agu_icb_cmd_smode                         = sdb_o_smode                              ;
  assign agu_icb_cmd_dmode                         = sdb_o_dmode                              ;
  assign agu_icb_cmd_wdata             [  63:   0] = sdb_o_wdata                   [  63:   0];
  assign agu_icb_cmd_wmask             [   7:   0] = sdb_o_wmask                   [   7:   0];
  assign agu_icb_cmd_size              [   1:   0] = sdb_o_size                    [   1:   0];
  assign agu_icb_cmd_usign                         = sdb_o_usign                              ;
  assign agu_icb_cmd_itag              [   3:   0] = sdb_o_itag                    [   3:   0];
  assign agu_icb_cmd_flhw                          = sdb_o_flhw                               ;
  assign agu_icb_cmd_fpu_dp                        = sdb_o_fpu_dp                             ;
  assign agu_icb_cmd_fpu_sp                        = sdb_o_fpu_sp                             ;
  assign agu_icb_cmd_flags_fswh        [   4:   0] = sdb_o_flags_fswh              [   4:   0];
  assign agu_icb_cmd_busy = sdb_i_busy | sdb_not_empty;
  assign sdb_outstanding_valid = sdb_not_empty;
endmodule
