module e603_gnrl_stck # (
  parameter DP   = 8,
  parameter DW   = 32
) (
  input           i_wen,
  input  [DW-1:0] i_dat,
  input           o_ren,
  output [DW-1:0] o_dat,
  input           clk,
  input           rst_n
);
  
  wire [DW-1:0] stck_rf_r [DP-1:0];
  wire [DP-1:0] stck_rf_en;
  
  
  wire [DP:0] i_vec;
  wire [DP:0] o_vec;
  wire [DP:0] vec_nxt;
  wire [DP:0] vec_r;
  wire vec_en = (o_ren ^ i_wen );
  assign vec_nxt = i_wen ? (vec_r << 1) : (vec_r >> 1);
  e603_gnrl_dfflrs #(1)  vec_0_dfflrs(vec_en, vec_nxt[0]   , vec_r[0]   , clk, rst_n);
  e603_gnrl_dfflr  #(DP) vec_dp_dfflr(vec_en, vec_nxt[DP:1], vec_r[DP:1], clk, rst_n);
  assign i_vec = vec_r; 
  assign o_vec = (vec_r >> 1); 
  genvar i;
  generate 
    
    for (i=0; i<DP; i=i+1) begin:gen_stck_rf
      assign stck_rf_en[i] = i_wen & i_vec[i];      
      e603_gnrl_dffl  #(DW) stck_rf_dffl (stck_rf_en[i], i_dat, stck_rf_r[i], clk, rst_n);
    end
  endgenerate
  
  integer j;
  reg [DW-1:0] mux_rdat;
  always @*
  begin : rd_port_PROC
    mux_rdat = {DW{1'b0}};
    for(j=0; j<DP; j=j+1) begin
      mux_rdat = mux_rdat | ({DW{o_vec[j]}} & stck_rf_r[j]);
    end
  end
  assign o_dat = mux_rdat;
endmodule
module e603_gnrl_ratio_fifo # (
  parameter I_SUPPORT_RATIO = 0,
  parameter O_SUPPORT_RATIO = 0,
  parameter DP   = 8,
  parameter DW   = 32
) (
  input           i_clk_en,
  input           i_vld,
  output          i_rdy,
  input  [DW-1:0] i_dat,
  input           o_clk_en,
  output          o_vld,
  input           o_rdy,
  output [DW-1:0] o_dat,
  output          o_fifo_active,
  input           clk,
  input           rst_n
);
genvar i;
generate
  if(DP == 0) begin: gen_dp_eq1
     assign o_vld = i_vld;
     assign i_rdy = o_rdy;
     assign o_dat = i_dat;
     assign o_fifo_active =  i_vld;
  end
  else begin: gen_dp_gt0
    
    wire [DW-1:0] fifo_rf_r [DP-1:0];
    wire [DP-1:0] fifo_rf_en;
    
    wire wen = i_vld & i_rdy & i_clk_en;
    wire ren = o_vld & o_rdy & o_clk_en;
    
    
    wire [DP-1:0] rptr_vec_nxt;
    wire [DP-1:0] rptr_vec_r;
    wire [DP-1:0] wptr_vec_nxt;
    wire [DP-1:0] wptr_vec_r;
      if (DP == 1) begin:gen_wrptr_dp_1
          assign rptr_vec_nxt = 1'b1;
          assign wptr_vec_nxt = 1'b1;
      end
      else begin:gen_wrptr_dp_not_1
          assign rptr_vec_nxt =
            rptr_vec_r[DP-1] ? {{DP-1{1'b0}}, 1'b1} :
                            (rptr_vec_r << 1);
          assign wptr_vec_nxt =
            wptr_vec_r[DP-1] ? {{DP-1{1'b0}}, 1'b1} :
                            (wptr_vec_r << 1);
      end
    e603_gnrl_dfflrs #(1)    rptr_vec_0_dfflrs  (ren, rptr_vec_nxt[0]     , rptr_vec_r[0]     , clk, rst_n);
    e603_gnrl_dfflrs #(1)    wptr_vec_0_dfflrs  (wen, wptr_vec_nxt[0]     , wptr_vec_r[0]     , clk, rst_n);
      if(DP>1) begin:gen_dp_gt1
         e603_gnrl_dfflr  #(DP-1) rptr_vec_31_dfflr  (ren, rptr_vec_nxt[DP-1:1], rptr_vec_r[DP-1:1], clk, rst_n);
         e603_gnrl_dfflr  #(DP-1) wptr_vec_31_dfflr  (wen, wptr_vec_nxt[DP-1:1], wptr_vec_r[DP-1:1], clk, rst_n);
      end
    
    
    wire [DP:0] i_vec;
    wire [DP:0] o_vec;
    wire [DP:0] vec_nxt;
    wire [DP:0] vec_r;
    wire vec_en = (ren ^ wen );
    assign vec_nxt = wen ? {vec_r[DP-1:0], 1'b1} : (vec_r >> 1);
    e603_gnrl_dfflrs #(1)  vec_0_dfflrs     (vec_en, vec_nxt[0]     , vec_r[0]     ,     clk, rst_n);
    e603_gnrl_dfflr  #(DP) vec_31_dfflr     (vec_en, vec_nxt[DP:1], vec_r[DP:1],     clk, rst_n);
    assign i_vec = {1'b0,vec_r[DP:1]};
    assign o_vec = {1'b0,vec_r[DP:1]};
  wire fifo_i_active;
  if (!I_SUPPORT_RATIO) begin : gen_i_no_ratio
    assign i_rdy = (~i_vec[DP-1]);
    assign fifo_i_active = 1'b0;
  end
  else begin: gen_i_ratio
    wire i_rdy_r_ena;
    wire i_rdy_r_nxt;
    wire i_rdy_r;
    wire i_need_updat;
    wire i_need_updat_r_set;
    wire i_need_updat_r_clr;
    wire i_need_updat_r_ena;
    wire i_need_updat_r_nxt;
    wire i_need_updat_r;
    assign i_need_updat = vec_en;
    assign i_need_updat_r_set = (i_need_updat && !i_clk_en);
    assign i_need_updat_r_clr = (i_need_updat_r && i_clk_en);
    assign i_need_updat_r_ena = i_need_updat_r_set || i_need_updat_r_clr;
    assign i_need_updat_r_nxt = i_need_updat_r_set;
    e603_gnrl_dfflr  #(1) i_need_updat_r_dfflr    (i_need_updat_r_ena, i_need_updat_r_nxt, i_need_updat_r,     clk, rst_n);
    assign i_rdy_r_ena = i_clk_en && (i_need_updat || i_need_updat_r);
    assign i_rdy_r_nxt = (vec_en) ? (~vec_nxt[DP]) : (~i_vec[DP-1]);
    e603_gnrl_dfflrs  #(1) i_rdy_r_dfflrs    (i_rdy_r_ena, i_rdy_r_nxt, i_rdy_r,     clk, rst_n);
    assign i_rdy = i_rdy_r;
    assign fifo_i_active = i_need_updat_r;
`ifdef ASSERT_ON
//synopsys translate_off
      reg [DP:0] i_occp_r_ideal;
      wire i_rdy_ideal;
      wire [DP:0] i_occp_in;
      assign i_occp_in = vec_en ? vec_nxt: vec_r;
      always @(posedge clk or negedge rst_n)
      begin : i_occp_ideal_DFFEAR_PROC
        if (rst_n == 1'b0)
          i_occp_r_ideal <= { {DP{1'b0}}, 1'b1};
        else if (i_clk_en == 1'b1)
          i_occp_r_ideal <= i_occp_in;
      end
      assign i_rdy_ideal = (~i_occp_r_ideal[DP]);
      CHECK_IF_IRDY_IS_CORRECT:
        assert property (@(posedge clk) disable iff(rst_n === 1'bx || rst_n == 1'b0)
                         (~(i_rdy_ideal != i_rdy))
                        )
        else $fatal ("\n Error: should never happen, i_rdy should be equal to i_rdy! \n");
//synopsys translate_on
`endif
  end
    
    for (i=0; i<DP; i=i+1) begin:gen_fifo_rf
      assign fifo_rf_en[i] = wen & wptr_vec_r[i];
      
      e603_gnrl_dfflr  #(DW) fifo_rf_dffl (fifo_rf_en[i], i_dat, fifo_rf_r[i], clk, rst_n);
    end
    
    integer j;
    reg [DW-1:0] mux_rdat;
    always @*
    begin : rd_port_PROC
      mux_rdat = {DW{1'b0}};
      for(j=0; j<DP; j=j+1) begin
        mux_rdat = mux_rdat | ({DW{rptr_vec_r[j]}} & fifo_rf_r[j]);
      end
    end
    
    assign o_dat = mux_rdat & {DW{o_vld}};
  wire fifo_o_active;
  if (!O_SUPPORT_RATIO) begin : gen_o_no_ratio
    
    assign o_vld = (o_vec[0]);
    assign fifo_o_active = 1'b0;
  end
  else begin : gen_o_ratio
    wire o_vld_r_ena;
    wire o_vld_r_nxt;
    wire o_vld_r;
    wire o_need_updat;
    wire o_need_updat_r_set;
    wire o_need_updat_r_clr;
    wire o_need_updat_r_ena;
    wire o_need_updat_r_nxt;
    wire o_need_updat_r;
    assign o_need_updat = vec_en;
    assign o_need_updat_r_set = (o_need_updat   && !o_clk_en);
    assign o_need_updat_r_clr = (o_need_updat_r &&  o_clk_en);
    assign o_need_updat_r_ena = o_need_updat_r_set || o_need_updat_r_clr;
    assign o_need_updat_r_nxt = o_need_updat_r_set;
    e603_gnrl_dfflr  #(1) o_need_updat_r_dfflr    (o_need_updat_r_ena, o_need_updat_r_nxt, o_need_updat_r,     clk, rst_n);
    assign o_vld_r_ena = o_clk_en && (o_need_updat || o_need_updat_r);
    assign o_vld_r_nxt = (vec_en) ? (vec_nxt[1]) : (o_vec[0]);
    e603_gnrl_dfflr  #(1) o_vld_r_dfflr    (o_vld_r_ena, o_vld_r_nxt, o_vld_r,     clk, rst_n);
    assign o_vld = o_vld_r;
    assign fifo_o_active = o_need_updat_r;
`ifdef ASSERT_ON
//synopsys translate_off
      reg [DP:0] o_occp_r_ideal;
      wire o_vld_ideal;
      wire [DP:0] o_occp_in;
      assign o_occp_in = vec_en ? vec_nxt: vec_r;
      always @(posedge clk or negedge rst_n)
      begin : o_occp_ideal_DFFEAR_PROC
        if (rst_n == 1'b0)
          o_occp_r_ideal <= { {DP{1'b0}}, 1'b1};
        else if (o_clk_en == 1'b1)
          o_occp_r_ideal <= o_occp_in;
      end
      assign o_vld_ideal = (o_occp_r_ideal[1]);
      CHECK_IF_OVLD_IS_CORRECT:
        assert property (@(posedge clk) disable iff(rst_n === 1'bx || rst_n == 1'b0)
                         (~(o_vld_ideal != o_vld))
                        )
        else $fatal ("\n Error: should never happen, o_vld should be equal to o_vld! \n");
//synopsys translate_on
`endif
  end
  assign o_fifo_active =  i_vld || fifo_i_active || o_vld || fifo_o_active;
`ifdef ASSERT_ON
//synopsys translate_off
  I_CLK_RATIO_CHECK:
  assert property (@(posedge clk) disable iff (~rst_n)
                                      (!i_clk_en) |=> $stable(
                                                                {
                                                                  i_rdy
                                                                }
                                                               )
  ) else $fatal ("\n Error: Signals are not stable when i-clock ratioed!!!\n");
  O_CLK_RATIO_CHECK:
  assert property (@(posedge clk) disable iff (~rst_n)
                                      (!o_clk_en) |=> $stable(
                                                                {
                                                                  o_vld,
                                                                  (o_dat)
                                                                }
                                                               )
  ) else $fatal ("\n Error: Signals are not stable when o-clock ratioed!!!\n");
//synopsys translate_on
`endif
  end
endgenerate
endmodule
module e603_gnrl_loop_stck # (
    parameter DP = 4,
    parameter DW = 32
)(
    input  i_wen,
    input  o_ren,
    input  [DW-1:0] i_dat,
    output [DW-1:0] o_dat,
    input  clk,
    input  rst_n
);
  
  wire [DW-1:0] stck_rf_r [DP-1:0];
  wire [DP-1:0] stck_rf_en;
  
  
  wire [DP-1:0] i_vec;
  wire [DP-1:0] o_vec;
  wire [DP-1:0] vec_nxt;
  wire [DP-1:0] vec_r;
  wire vec_en = (o_ren ^ i_wen);
  assign vec_nxt =     o_ren ?
                   (vec_r[0] ? {1'b1,{DP-1{1'b0}}} : (vec_r >> 1)) :
                (vec_r[DP-1] ? {{DP-1{1'b0}},1'b1} : (vec_r << 1))
                             ;
  e603_gnrl_dfflrs #(1)    vec_0_dfflrs(vec_en, vec_nxt[0]     , vec_r[0]     , clk, rst_n);
  e603_gnrl_dfflr  #(DP-1) vec_dp_dfflr(vec_en, vec_nxt[DP-1:1], vec_r[DP-1:1], clk, rst_n);
  assign i_vec = vec_r; 
  assign o_vec = (vec_r == {{DP-1{1'b0}},1'b1}) ? {1'b1, {DP-1{1'b0}}}
                                                : (vec_r >> 1); 
  genvar i;
  generate 
    
    for (i=0; i<DP; i=i+1) begin:gen_stck_rf
      assign stck_rf_en[i] = i_wen & i_vec[i];      
      e603_gnrl_dfflr  #(DW) stck_rf_dfflr (stck_rf_en[i], i_dat, stck_rf_r[i], clk, rst_n);
    end
  endgenerate
  
  integer j;
  reg [DW-1:0] mux_rdat;
  always @*
  begin : rd_port_PROC
    mux_rdat = {DW{1'b0}};
    for(j=0; j<DP; j=j+1) begin
      mux_rdat = mux_rdat | ({DW{o_vec[j]}} & stck_rf_r[j]);
    end
  end
  assign o_dat = mux_rdat;
endmodule
module e603_gnrl_cdc_buf
# (
  parameter DW = 32,
  parameter SYNC_DP = 2
) (
  input  i_clk,
  input  i_rst_n,
  input  i_vld,
  output i_rdy,
  input  [DW-1:0] i_dat,
  output i_cdc_buf_active,
  output o_cdc_buf_active,
  input  o_clk,
  input  o_rst_n,
  output o_vld,
  input  o_rdy,
  output [DW-1:0] o_dat
);
  wire tx_vld;
  wire tx_rdy;
  wire [DW-1:0] tx_dat;
  e603_gnrl_cdc_tx # (
    .DW(DW),
    .SYNC_DP(SYNC_DP)
  ) u_cmd_cdc_tx(
    .i_vld  (i_vld),
    .i_rdy  (i_rdy),
    .i_dat  (i_dat),
    .o_vld  (tx_vld ),
    .o_rdy_a(tx_rdy ),
    .o_dat  (tx_dat),
    .clk    (i_clk),
    .rst_n  (i_rst_n)
  );
  e603_gnrl_cdc_rx # (
    .DW(DW),
    .SYNC_DP(SYNC_DP)
   ) u_cmd_cdc_rx(
    .i_vld_a (tx_vld ),
    .i_rdy   (tx_rdy ),
    .i_dat   (tx_dat),
    .o_vld   (o_vld),
    .o_rdy   (o_rdy),
    .o_dat   (o_dat ),
    .clk    (o_clk),
    .rst_n  (o_rst_n)
  );
  assign i_cdc_buf_active = i_vld  | tx_vld;
  assign o_cdc_buf_active = tx_rdy | o_vld;
endmodule
module e603_gnrl_2w1r_fifo # (
  parameter CUT_READY = 0,
  parameter MSKO = 0,
  parameter FIFO_REG_OUT = 0,
  parameter DP   = 8,
  parameter DW   = 32
) (
  input           i_vld0,
  input           i_vld1,
  output          i_rdy,
  input  [DW-1:0] i_dat0,
  input  [DW-1:0] i_dat1,
  output          o_vld,
  input           o_rdy,
  output [DW-1:0] o_dat,
  input           clk,
  input           rst_n
);
    
    wire [DW-1:0] fifo_rf_din [DP-1:0];
    wire [DW-1:0] fifo_rf_wdat [DP-1:0];
    wire [DW-1:0] fifo_rf_r [DP-1:0];
    wire [DP-1:0] fifo_rf_en0;
    wire [DP-1:0] fifo_rf_en1;
    wire [DP-1:0] fifo_rf_en;
    
    wire wen0 = i_vld0 & i_rdy;
    wire wen1 = i_vld1 & i_rdy;
    wire wen = (i_vld0 | i_vld1) & i_rdy;
    wire ren = o_vld & o_rdy;
    wire dual_wen = wen0 & wen1;
    
    
    wire [DP-1:0] rptr_vec_nxt;
    wire [DP-1:0] rptr_vec_din;
    wire [DP-1:0] rptr_vec_r;
    wire [DP-1:0] wptr_vec_nxt;
    wire [DP-1:0] wptr_vec_r;
    wire [DP-1:0] wptr_vec_r_lshift_1 = wptr_vec_r << 1;
    wire [DP-1:0] wptr0_vec_r = wptr_vec_r;
    wire [DP-1:0] wptr1_vec_r = wptr_vec_r[DP-1] ? {{DP-1{1'b0}}, 1'b1} : wptr_vec_r_lshift_1;
    assign rptr_vec_nxt =
          rptr_vec_r[DP-1] ? {{DP-1{1'b0}}, 1'b1} :
                          (rptr_vec_r << 1);
    assign wptr_vec_nxt =
          wptr_vec_r[DP-1] ? (dual_wen ? {{DP-2{1'b0}}, 2'b10} : {{DP-1{1'b0}}, 1'b1}):
          wptr_vec_r[DP-2] ? (dual_wen ? {{DP-1{1'b0}}, 1'b1}  : wptr_vec_r_lshift_1):
                             (dual_wen ? (wptr_vec_r << 2)    : wptr_vec_r_lshift_1);
    e603_gnrl_dfflrs #(1)    rptr_vec_0_dfflrs (ren, rptr_vec_nxt[0]     , rptr_vec_r[0]     , clk, rst_n);
    e603_gnrl_dfflrs #(1)    wptr_vec_0_dfflrs (wen, wptr_vec_nxt[0]     , wptr_vec_r[0]     , clk, rst_n);
    e603_gnrl_dfflr  #(DP-1) rptr_vec_31_dfflr (ren, rptr_vec_nxt[DP-1:1], rptr_vec_r[DP-1:1], clk, rst_n);
    e603_gnrl_dfflr  #(DP-1) wptr_vec_31_dfflr (wen, wptr_vec_nxt[DP-1:1], wptr_vec_r[DP-1:1], clk, rst_n);
    assign rptr_vec_din = ren  ? rptr_vec_nxt : rptr_vec_r;
    
    
    wire [DP:0] i_vec;
    wire [DP:0] o_vec;
    wire [DP:0] vec_nxt;
    wire [DP:0] vec_r;
    wire vec_en =
                 (~(   (~(ren | wen0 | wen1)) 
                      | (ren & (wen0 ^ wen1))  
                    ))
                ;
    assign vec_nxt =
                        ((~ren) & wen0 & wen1)  ? {vec_r[DP-2:0], 2'b11} :
                      (ren & (~wen0) & (~wen1)) ? (vec_r >> 1)
                                                : {vec_r[DP-1:0], 1'b1}
                                                ;
    e603_gnrl_dfflrs #(1)  vec_0_dfflrs     (vec_en, vec_nxt[0]   , vec_r[0]   ,     clk, rst_n);
    e603_gnrl_dfflr  #(DP) vec_31_dfflr     (vec_en, vec_nxt[DP:1], vec_r[DP:1],     clk, rst_n);
    assign i_vec = {1'b0,vec_r[DP:1]};
    assign o_vec = {1'b0,vec_r[DP:1]};
    genvar i;
    generate 
    
    
    
    
    assign i_rdy = (~i_vec[DP-2]) | ((~i_vec[DP-1]) & (~(i_dat0[DW-1] & i_dat1[DW-1])));
      
      for (i=0; i<DP; i=i+1) begin:gen_fifo_rf
        assign fifo_rf_en0[i] = (wen0 & wptr0_vec_r[i]);
        assign fifo_rf_en1[i] = (wen1 & wptr1_vec_r[i]);
        assign fifo_rf_en[i]  = fifo_rf_en0[i] | fifo_rf_en1[i];
        assign fifo_rf_wdat[i] = ({DW{fifo_rf_en0[i]}} & i_dat0)
                               | ({DW{fifo_rf_en1[i]}} & i_dat1)
                               ;
        
        e603_gnrl_dfflr  #(DW) fifo_rf_dfflr (fifo_rf_en[i],fifo_rf_wdat[i], fifo_rf_r[i], clk, rst_n);
        assign fifo_rf_din[i] = fifo_rf_en[i] ? fifo_rf_wdat[i] : fifo_rf_r[i];
      end
    
    integer j;
    reg [DW-1:0] mux_rdat;
    if(FIFO_REG_OUT == 0) begin:gen_rdat_output
        always @*
        begin : rd_port_PROC
          mux_rdat = {DW{1'b0}};
          for(j=0; j<DP; j=j+1) begin
            mux_rdat = mux_rdat | ({DW{rptr_vec_r[j]}} & fifo_rf_r[j]);
          end
        end
    end
    else begin:gen_rdat_flp_output
        reg [DW-1:0] mux_rdat_din;
        wire [DW-1:0] mux_rdat_r;
        always @*
        begin : rd_port_PROC
          mux_rdat_din = {DW{1'b0}};
          for(j=0; j<DP; j=j+1) begin
            mux_rdat_din = mux_rdat_din | ({DW{rptr_vec_din[j]}} & fifo_rf_din[j]);
          end
        end
        e603_gnrl_dffr #(DW) mux_rdat_dffr  (mux_rdat_din, mux_rdat_r, clk, rst_n);
        always @*
        begin : direct_assign
            mux_rdat = mux_rdat_r;
        end
    end
    endgenerate
    
    
    assign o_dat = mux_rdat;
    
    assign o_vld = (o_vec[0]);
endmodule
module e603_gnrl_cdc_pulse
# (
  parameter SYNC_DP = 2
) (
  input  i_clk,
  input  i_rst_n,
  input  i_pulse,
  output i_active,
  output o_active,
  input  o_clk,
  input  o_rst_n,
  output o_pulse
);
e603_gnrl_cdc_buf
# (
    .DW         (1      ),
    .SYNC_DP    (SYNC_DP)
) u_gnrl_cdc_buf (
    .i_clk           (i_clk       ),
    .i_rst_n         (i_rst_n     ),
    .i_vld           (i_pulse     ),
    .i_rdy           (            ),
    .i_dat           (1'b0        ),
    .i_cdc_buf_active(i_active    ),
    .o_cdc_buf_active(o_active    ),
    .o_clk           (o_clk       ),
    .o_rst_n         (o_rst_n     ),
    .o_vld           (o_pulse     ),
    .o_rdy           (1'b1        ),
    .o_dat           (            )
);
endmodule
module e603_gnrl_cdc_fifo #(
  
  parameter DP   = 5,
  parameter DP_PTR_W   = 3,
  parameter DW   = 32,
  parameter SYNC_DP = 2
) (
  input  i_clk,
  input  i_rst_n,
  input  i_vld,
  output i_rdy,
  input  [DW-1:0] i_dat,
  output i_cdc_fifo_active,
  output o_cdc_fifo_active,
  input  o_clk,
  input  o_rst_n,
  output o_vld,
  input  o_rdy,
  output [DW-1:0] o_dat
);
  wire          wr   ;
  wire [DW-1:0] wdata;
  wire          full ;
  wire          rd   ;
  wire [DW-1:0] rdata;
  wire          empty;
  wire          w_empty;
  e603_gnrl_async_fifo #(.DW(DW), .DP(DP),  .DP_PTR_W(DP_PTR_W), .SYNC_DP(SYNC_DP))
  u_a_fifo (
  
    .wclk     (i_clk),
    .wrst_n   (i_rst_n),
    .wr       (wr),
    .wdata    (wdata),
    .wwmk     (),
    .full     (full),
    .w_empty  (w_empty),
  
    .rclk     (o_clk),
    .rrst_n   (o_rst_n),
    .rd       (rd),
    .rdata    (rdata),
    .rwmk     (),
    .empty    (empty)
  );
  assign i_rdy = ~full;
  assign wr = i_vld & i_rdy;
  assign wdata = i_dat;
  assign o_vld = ~empty;
  assign rd = o_vld & o_rdy;
  assign o_dat = rdata;
  assign i_cdc_fifo_active = (~w_empty);
  assign o_cdc_fifo_active = ~empty;
endmodule
module e603_gnrl_data_mux (
  out_data
  , in_data
  , sel
  );
  parameter DW = 8;
  parameter N  = 2;
  localparam SW = N<=1 ? 1 : N<=2**0 ? 0 : N<=2**1 ? 1 : N<=2**2 ? 2 : N<=2**3 ? 3 : N<=2**4 ? 4 : N<=2**5 ? 5 : N<=2**6 ? 6 :
                    N<=2**7 ? 7 : N<=2**8 ? 8 : N<=2**9 ? 9 : N<=2**10 ? 10 : N<=2**11 ? 11 :
                    N<=2**12 ? 12 : N<=2**13 ? 13 : N<=2**14 ? 14 : N<=2**15 ? 15 : N<=2**16 ? 16
                    : N<=2**17 ? 17 : N<=2**18 ? 18 : N<=2**19 ? 19 : N<=2**20 ? 20 : N<=2**21 ?
                    21 : N<=2**22 ? 22 : N<=2**23 ? 23 : N<=2**24 ? 24 : N<=2**25 ? 25 : N<=2**26
                    ? 26 : N<=2**27 ? 27 : N<=2**28 ? 28 : N<=2**29 ? 29 : N<=2**30 ? 30 :
                    N<=2**31 ? 31 : 32;
  output   [DW-1:0] out_data;
  input  [N*DW-1:0] in_data;
  input    [SW-1:0] sel;
  wire [DW-1:0] in_data_xy [N-1:0];
  wire  [N-1:0] in_data_yx [DW-1:0];
  wire  [N-1:0] in_data_mask;
  genvar gvi, gvj;
`ifdef ASSERT_ON
//synopsys translate_off
  // VCS coverage off
  initial begin: PROC_param_check
    if (N <= 0)
      $display("Error: %m.N (%d) must be greater than 0", N);
  end // PROC_param_check
  // VCS coverage on
//synopsys translate_on
`endif
  generate
  for (gvi=0; gvi<N; gvi=gvi+1) begin: GEN_in_data_xy
    assign in_data_xy[gvi] = in_data[gvi*DW +: DW];
    assign in_data_mask[gvi] = (gvi[SW-1:0] == sel);
    for (gvj=0; gvj<DW; gvj=gvj+1) begin: GEN_in_data_yx
      assign in_data_yx[gvj][gvi] = in_data_xy[gvi][gvj];
    end 
  end 
  for (gvi=0; gvi<DW; gvi=gvi+1) begin: GEN_out_data
    assign out_data[gvi] = |(in_data_mask & in_data_yx[gvi]);
  end 
  endgenerate
endmodule
module e603_gnrl_mem_line (clk, rst_n, wr, wdata, mem);
  parameter DW = 8;
  input           clk;
  input           rst_n;
  input           wr;
