  if (ZEROCYC_RSP == 1) begin:gen_0cyc_rsp_1
      e603_gnrl_bypbuf #(
              .DP  (FIFO_OUTS_NUM),
              .DW  (2)
      )  u_n2w_bypbuf(
          .i_vld(n2w_fifo_i_valid),
          .i_rdy(n2w_fifo_i_ready),
          .i_dat({cmd_y_lo_hi, cmd_y_merged} ),
          .o_dat({rsp_y_lo_hi, rsp_y_merged} ),
