        assign i_icb_cmd_size_full = (i_icb_cmd_size[2:0] == 3'b100);
        assign i_icb_cmd_addr_lowr = ~i_icb_cmd_addr[4];
    end
    if(X_W == 256) begin: gen_x_w_256
