  e603_gnrl_dfflr #(X_W)  icb_2nd_cmd_wdata(merg_buf_ena, i_icb_cmd_wdata, icb_2nd_cmd_wdata_r, clk, rst_n);
  e603_gnrl_dfflr #(X_W/8)icb_2nd_cmd_wmask(merg_buf_ena, i_icb_cmd_wmask, icb_2nd_cmd_wmask_r, clk, rst_n);
  e603_gnrl_dfflr #(1)    icb_2nd_cmd_beat0(merg_buf_ena, i_icb_cmd_beat0 , icb_2nd_cmd_beat0_r , clk, rst_n);
  
  assign o_icb_cmd_sel   = (~n2w_fifo_full) & (i_icb_cmd_sel   | icb_2nd_cmd_valid_r);
  assign o_icb_cmd_valid = (~n2w_fifo_full) & (i_icb_cmd_need_merg ? (i_icb_cmd_valid & icb_2nd_cmd_valid_r) : i_icb_cmd_valid);
  assign i_icb_cmd_ready = (~n2w_fifo_full) & ((i_icb_cmd_need_merg & (~icb_2nd_cmd_valid_r)) ? 1'b1 : o_icb_cmd_ready);
  assign o_icb_cmd_addr  = icb_2nd_cmd_valid_r ? icb_2nd_cmd_addr_r : i_icb_cmd_addr;
  assign o_icb_cmd_wdata = icb_2nd_cmd_valid_r ? {i_icb_cmd_wdata, icb_2nd_cmd_wdata_r} : o_icb_cmd_wdata_pre;
  assign o_icb_cmd_wmask = icb_2nd_cmd_valid_r ? {i_icb_cmd_wmask, icb_2nd_cmd_wmask_r} : o_icb_cmd_wmask_pre;
  assign o_icb_cmd_read   = i_icb_cmd_read;
  assign o_icb_cmd_lock   = i_icb_cmd_lock;
  assign o_icb_cmd_excl   = i_icb_cmd_excl;
  assign o_icb_cmd_usr    = i_icb_cmd_usr;
  assign o_icb_cmd_xburst = i_icb_cmd_xburst;
  assign o_icb_cmd_modes  = i_icb_cmd_modes ;
  assign o_icb_cmd_dmode  = i_icb_cmd_dmode ;
  assign o_icb_cmd_attri  = i_icb_cmd_attri ;
   
  assign o_icb_cmd_beat[0] = icb_2nd_cmd_valid_r ? icb_2nd_cmd_beat0_r : i_icb_cmd_beat[0];
   
  assign o_icb_cmd_beat[1] = i_icb_cmd_beat[1] & (~(icb_2nd_cmd_valid_r & i_icb_cmd_xlen_is1));
  generate
