    assign o_icb_cmd_size = icb_2nd_cmd_valid_r ? 3'b011 : i_icb_cmd_size;
    assign o_icb_cmd_xlen = icb_2nd_cmd_valid_r ? {1'b0,i_icb_cmd_xlen[7:1]} : i_icb_cmd_xlen;
  end
  if (X_W == 64) begin:dw_128_o_icb
