    assign o_icb_cmd_xlen = icb_2nd_cmd_valid_r ? {1'b0,i_icb_cmd_xlen[7:1]} : i_icb_cmd_xlen;
  end
  if (X_W == 128) begin:dw_256_o_icb
    assign o_icb_cmd_size = icb_2nd_cmd_valid_r ? 3'b101 : i_icb_cmd_size;
    assign o_icb_cmd_xlen = icb_2nd_cmd_valid_r ? {1'b0,i_icb_cmd_xlen[7:1]} : i_icb_cmd_xlen;
  end
  if (X_W == 256) begin:dw_512_o_icb
