    e603_gnrl_dfflr #(1)     icb_2nd_cmd_excl   (icb_2nd_cmd_valid_set, i_icb_cmd_excl, icb_2nd_cmd_excl_r, clk, rst_n);
    e603_gnrl_dfflr #(1)     icb_2nd_cmd_read   (icb_2nd_cmd_valid_set, i_icb_cmd_read, icb_2nd_cmd_read_r, clk, rst_n);
    e603_gnrl_dfflr #(AW-3)  icb_2nd_cmd_addr   (icb_2nd_cmd_valid_set, i_icb_cmd_addr[AW-1:3], icb_2nd_cmd_addr_r, clk, rst_n);
    e603_gnrl_dfflr #(Y_W)   icb_2nd_cmd_wdata  (icb_2nd_cmd_valid_set, i_icb_cmd_wdata[X_W-1:Y_W], icb_2nd_cmd_wdata_r, clk, rst_n);
    e603_gnrl_dfflr #(Y_W/8) icb_2nd_cmd_wmask  (icb_2nd_cmd_valid_set, i_icb_cmd_wmask[X_W/8-1:Y_W/8], icb_2nd_cmd_wmask_r, clk, rst_n);
    e603_gnrl_dfflr #(CMD_UW)icb_2nd_cmd_usr    (icb_2nd_cmd_valid_set, i_icb_cmd_usr, icb_2nd_cmd_usr_r, clk, rst_n);
