    e603_gnrl_dfflr #(8)     icb_2nd_cmd_xlen   (icb_2nd_cmd_valid_set, i_icb_cmd_xlen  , icb_2nd_cmd_xlen_r, clk, rst_n);
    e603_gnrl_dfflr #(2)     icb_2nd_cmd_xburst (icb_2nd_cmd_valid_set, i_icb_cmd_xburst, icb_2nd_cmd_xburst_r, clk, rst_n);
    e603_gnrl_dfflr #(2)     icb_2nd_cmd_modes  (icb_2nd_cmd_valid_set, i_icb_cmd_modes , icb_2nd_cmd_modes_r, clk, rst_n);
    e603_gnrl_dfflr #(1)     icb_2nd_cmd_dmode  (icb_2nd_cmd_valid_set, i_icb_cmd_dmode , icb_2nd_cmd_dmode_r, clk, rst_n);
    e603_gnrl_dfflr #(3)     icb_2nd_cmd_attri  (icb_2nd_cmd_valid_set, i_icb_cmd_attri , icb_2nd_cmd_attri_r, clk, rst_n);
    
    assign o_icb_cmd_sel   = (~w2n_fifo_full) & i_icb_cmd_sel   || icb_2nd_cmd_valid_r;
    assign o_icb_cmd_valid = (~w2n_fifo_full) & i_icb_cmd_valid || icb_2nd_cmd_valid_r;
    assign o_icb_cmd_addr = icb_2nd_cmd_valid_r ? (
                                                  
                                                    (X_W == 64) ? {icb_2nd_cmd_addr_r[AW-1:3],3'b100} :
                                                  
                                                    (X_W == 256) ? {icb_2nd_cmd_addr_r[AW-1:5],5'b10000} :
                                                  
                                                    (X_W == 512) ? {icb_2nd_cmd_addr_r[AW-1:6],6'b100000} :
                                                  
                                                                  {icb_2nd_cmd_addr_r[AW-1:4],4'b1000}
                                                    ) :
                             
                             icb_cmd_size_dw    ? (
                                                  
