                                                    (X_W == 256) ? {i_icb_cmd_addr[AW-1:5],5'b0} :
                                                  
                                                    (X_W == 512) ? {i_icb_cmd_addr[AW-1:6],6'b0} :
                                                  
                                                                  {i_icb_cmd_addr[AW-1:4],4'b0}
                                                    )
