    assign o_icb_cmd_lock = icb_2nd_cmd_valid_r ? icb_2nd_cmd_lock_r
                                                : i_icb_cmd_lock;
    assign o_icb_cmd_excl = icb_2nd_cmd_valid_r ? icb_2nd_cmd_excl_r
