  wire icb_rsp_leftover_ena = icb_rsp_size_dw &  o_icb_rsp_hasked & (~icb_2nd_rsp_valid_r);
  wire [Y_W-1:0] icb_rsp_leftover_rdata_nxt = o_icb_rsp_rdata[Y_W-1:0];
  wire [Y_W-1:0] icb_rsp_leftover_rdata_r;
