  wire icb_rsp_leftover_err_r;
  e603_gnrl_dfflr #(1) icb_rsp_leftover_err_dfflr(icb_rsp_leftover_ena, icb_rsp_leftover_err_nxt, icb_rsp_leftover_err_r, clk, rst_n);
  
