                                                  {{Y_W{1'b0}}, o_icb_rsp_rdata}
                                                ;
  assign o_icb_rsp_ready = (icb_rsp_size_dw & (~icb_2nd_rsp_valid_r)) ? 1'b1 : i_icb_rsp_ready;
  assign i_icb_rsp_err   = icb_rsp_leftover_vld ? |{icb_rsp_leftover_err_r, o_icb_rsp_err} : o_icb_rsp_err;
  assign i_icb_rsp_excl_ok = 1'b0;
  assign i_icb_rsp_usr   = o_icb_rsp_usr;
