module e603_gnrl_ficb_id_gen # (
  parameter OUTS_FIFO_DP = 8,
  parameter ID_W = 32 
) (
  input              i_icb_cmd_valid, 
  input              i_icb_cmd_ready, 
  input  [ID_W -1:0] i_icb_cmd_id,
  input  [2    -1:0] i_icb_cmd_xburst,
  input  [2    -1:0] i_icb_cmd_beat,
  input  [8    -1:0] i_icb_cmd_xlen,
  output [2    -1:0] o_icb_cmd_beat,
  output [8    -1:0] o_icb_cmd_xlen,
  output             ficb_id_gen_ready,
  input              i_icb_rsp_valid, 
  input              i_icb_rsp_ready, 
  output [ID_W -1:0] i_icb_rsp_id,
  output             i_icb_rsp_last,
  
  input  clk,  
  input  rst_n
  );
  wire i_icb_cmd_fixed = (i_icb_cmd_xburst == 2'b00);
  assign o_icb_cmd_beat = i_icb_cmd_fixed ? 2'b0 : i_icb_cmd_beat;
  assign o_icb_cmd_xlen = i_icb_cmd_fixed ? 8'b0 : i_icb_cmd_xlen;
  wire i_icb_cmd_last = i_icb_cmd_beat[1] | (i_icb_cmd_xlen == 8'd0);
  wire i_icb_cmd_hsked = i_icb_cmd_valid & i_icb_cmd_ready;
  wire i_icb_rsp_hsked = i_icb_rsp_valid & i_icb_rsp_ready;
     e603_gnrl_fifo # (
        .REG_OUT(0),
        .CUT_READY (1),
        .DP  (OUTS_FIFO_DP+1),
        .DW  (ID_W+1)
      ) u_e603_gnrl_rspid_fifo (
        .i_vld(i_icb_cmd_hsked),
        .i_rdy(ficb_id_gen_ready),
        .i_dat({i_icb_cmd_last,i_icb_cmd_id}),
        .o_vld(),
        .o_rdy(i_icb_rsp_hsked),
        .o_dat({i_icb_rsp_last,i_icb_rsp_id} ),
        .clk  (clk),
        .rst_n(rst_n)
      );
endmodule
module e603_gnrl_rbin4 # (
    parameter ARBT_NUM = 4
)(
  output[ARBT_NUM-1:0] grt_vec,  
  input [ARBT_NUM-1:0] req_vec,  
  input arbt_ena,   
  output rbin4_active,
  input clk,        
  input rst_n
);
  wire [ARBT_NUM-1:0] req_vec_mask;
  wire [ARBT_NUM-1:0] mask_r;
  genvar i;
  generate
      for(i = 0; i < ARBT_NUM; i = i+1)
      begin:gen_priroty_grt_vec
        if(i==0) begin: gen_i_is_0
		    
          assign grt_vec[i] =  ~req_vec_mask[0];
        end
        else if(i==(ARBT_NUM-1)) begin: gen_i_is_msb
		    
          assign grt_vec[i] =  (~(|req_vec[i-1:0])) | req_vec_mask[0];
        end
        else begin:gen_i_is_not_0_and_msb
          assign grt_vec[i] =  (~(|req_vec[i-1:0])) & (~req_vec_mask[i]);
        end
      end
  endgenerate
  localparam CNT_W = 2;
  localparam CNT_3 = 3;
  wire [CNT_W-1:0] cnt_r;
  
  wire cnt_inc = req_vec[ARBT_NUM-1] & (~grt_vec[ARBT_NUM-1]);
  
  
  wire cnt_clr_raw =  grt_vec[ARBT_NUM-1];
  wire cnt_clr =  cnt_clr_raw & (|cnt_r);
  wire cnt_ena = cnt_inc | cnt_clr;
  wire [CNT_W-1:0] cnt_nxt = cnt_inc ? (cnt_r + 1'b1) : {CNT_W{1'b0}};
  e603_gnrl_dfflr #(CNT_W) cnt_dfflr (cnt_ena, cnt_nxt, cnt_r, clk, rst_n);
  wire cnt_is_3 = (cnt_r == CNT_3[CNT_W-1:0]);
    
  wire mask_set = cnt_is_3 & cnt_inc;
    
  wire mask_clr = (|mask_r) & cnt_clr_raw;
  wire mask_ena = mask_set | mask_clr;
  
  wire [ARBT_NUM-1:0] mask_nxt = mask_set ? {1'b0,{ARBT_NUM-1{1'b1}}} : {ARBT_NUM{1'b0}};
  e603_gnrl_dfflr #(ARBT_NUM) mask_dfflr (mask_ena, mask_nxt, mask_r, clk, rst_n);
  assign req_vec_mask = mask_r;
  
  assign rbin4_active = |mask_r; 
endmodule
module e603_gnrl_age_matrix #(
    parameter ENT_NUM = 4
    ) (
    input [ENT_NUM-1:0]           entry_alloc_en,
    output [ENT_NUM*ENT_NUM-1:0]  age_matrix_pack,
    input clk,
    input rst_n
    );
  genvar i,j;
  wire [ENT_NUM-1:0] older_matrix_ena  [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] older_matrix_next [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] older_matrix      [ENT_NUM-1:0];
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :older_1d
      for (j=0;j<ENT_NUM;j=j+1) begin :older_2d
        if (i < j) begin:gen_i_lt_j
          
          assign older_matrix_ena[i][j] = entry_alloc_en[i] || entry_alloc_en[j];
          assign older_matrix_next[i][j]= entry_alloc_en[i] ? 1'b1 :
                                          entry_alloc_en[j] ? 1'b0 :
                                                            1'b0 ;
          e603_gnrl_dfflr #(1) age_r (older_matrix_ena[i][j], older_matrix_next[i][j], older_matrix[i][j], clk, rst_n);
        end 
        else begin:gen_i_nlt_j
          assign older_matrix_ena[i][j] = 1'b0;
          assign older_matrix_next[i][j] = 1'b0;
          assign older_matrix[i][j] = 1'b0;
        end
      end
    end
  endgenerate
 
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :gen_age_matrix
      assign age_matrix_pack[i*ENT_NUM+:ENT_NUM] = older_matrix[i][ENT_NUM-1:0];
    end
  endgenerate 
endmodule
module e603_gnrl_ficb2axi_ar # (
  parameter AW = 32,
  parameter DW = 32,
  parameter RATIO_FIFO_DP = 2,
  parameter CMD_UW = 1 
) (
  input                         icb_cmd_sel,
  input                         icb_cmd_valid,
  output                        icb_cmd_ready,
  input                         icb_cmd_read, 
  input [AW-1:0]                icb_cmd_addr, 
  input [DW-1:0]                icb_cmd_wdata,
  input [DW/8-1:0]                icb_cmd_wmask,
  input [1:0]                   icb_cmd_beat,
  input                         icb_cmd_lock,
  input                         icb_cmd_excl,
  input [2:0]                   icb_cmd_size,
  input [CMD_UW-1:0]             icb_cmd_usr,
  input [7:0]                   icb_cmd_xlen,
  input [1:0]                   icb_cmd_xburst,
  input [1:0]                   icb_cmd_modes,
  input                         icb_cmd_dmode,
  input [2:0]                   icb_cmd_attri,
  input                         axi_arready,
  output                        axi_arvalid,
  output [AW-1:0]               axi_araddr,
  output [7:0]                  axi_arlen,
  output [2:0]                  axi_arsize,
  output [1:0]                  axi_arburst,
  output                        axi_arlock,
  output [3:0]                  axi_arcache,
  output [2:0]                  axi_arprot,
  output [CMD_UW-1:0]            axi_aruser,
  input                         axi_bus_clk_en,
  input                         icb_clk_en,
  input                         clk,
  input                         rst_n
  );
  localparam PACK_W = AW+8+3+1+2+4+3+CMD_UW;
  wire              i_arvalid;
  wire [AW-1:0]     i_araddr;
  wire [7:0]        i_arlen;
  wire [2:0]        i_arsize;
  wire [1:0]        i_arburst;
  wire              i_arlock;
  wire [3:0]        i_arcache;
  wire [2:0]        i_arprot;
  wire [CMD_UW-1:0]  i_aruser;
  wire [PACK_W-1:0] i_axi_pack;
  wire [PACK_W-1:0] o_axi_pack;
  wire i_axi_vld;
  wire i_axi_rdy;
  wire o_axi_vld;
  wire o_axi_rdy;
  wire axi_ar_ready;
  wire burst_flag_r;
  wire burst_flag_en;
  wire burst_flag_set;
  wire burst_flag_clr;
  assign burst_flag_en = burst_flag_set || burst_flag_clr;
  assign axi_ar_ready = axi_arready;
  
  assign burst_flag_set = icb_cmd_ready && icb_cmd_valid && icb_cmd_beat[0] & icb_clk_en;
  assign burst_flag_clr = burst_flag_r && icb_cmd_ready && icb_cmd_valid && icb_cmd_beat[1] & icb_clk_en;
  e603_gnrl_dfflr #(1) burst_flag_dfflr (burst_flag_en, burst_flag_set, burst_flag_r, clk, rst_n);
  
  assign icb_cmd_ready = i_axi_rdy | burst_flag_r;
  assign i_arvalid = icb_cmd_valid & (~burst_flag_r);
  assign i_araddr   = icb_cmd_addr;
  assign i_arlen     = icb_cmd_xlen[7:0];
  assign i_arburst   = icb_cmd_xburst[1:0];
  assign i_arsize    = icb_cmd_size;
  
  assign i_arlock    = icb_cmd_excl; 
  wire icb_cmd_mmode  = (icb_cmd_modes == 2'd0);
  wire icb_cmd_smode  = (icb_cmd_modes == 2'd2);
  wire icb_cmd_ifu    = icb_cmd_attri[0];
  wire icb_cmd_device = icb_cmd_attri[1];
  wire icb_cmd_nc     = icb_cmd_attri[2];
  assign i_arcache   =  icb_cmd_device ? 4'b0000 :
                        icb_cmd_nc     ? 4'b0011 : 4'b1111;
  assign i_arprot[0] = icb_cmd_mmode | icb_cmd_smode;
  assign i_arprot[1] = 1'b0; 
  assign i_arprot[2] = icb_cmd_ifu;
  assign i_aruser    = icb_cmd_usr;
  assign i_axi_pack = 
                      {
                        i_araddr,
                        i_arlen,
                        i_arsize,
                        i_arburst,
                        i_arlock,
                        i_arcache,
                        i_arprot,
                        i_aruser 
                      };
  assign {
           axi_araddr,
           axi_arlen,
           axi_arsize,
           axi_arburst,
           axi_arlock,
           axi_arcache,
           axi_arprot,
           axi_aruser 
         } = o_axi_pack;
  assign axi_arvalid = o_axi_vld;
  assign i_axi_vld = i_arvalid;
  assign o_axi_rdy = axi_ar_ready;
  
  e603_gnrl_ratio_fifo # (
        .I_SUPPORT_RATIO (1),
        .O_SUPPORT_RATIO (1),
        .DP  (RATIO_FIFO_DP),
        .DW  (PACK_W)
  ) u_axi_ar_fifo (
        .i_clk_en(icb_clk_en),
        .i_vld(i_axi_vld),
        .i_rdy(i_axi_rdy),
        .i_dat(i_axi_pack),
        .o_clk_en(axi_bus_clk_en),
        .o_vld(o_axi_vld),
        .o_rdy(o_axi_rdy),  
        .o_dat(o_axi_pack),  
      
        .o_fifo_active(),
        .clk  (clk),
        .rst_n(rst_n)
  );
endmodule
module e603_gnrl_ficb2axi_aw # (
  parameter AW = 32,
  parameter DW = 32,
  parameter RATIO_FIFO_DP = 2,
  parameter CMD_UW = 1
) (
  input                         icb_cmd_valid,
  output                        icb_cmd_ready,
  input [AW-1:0]                icb_cmd_addr, 
  input [7:0]                   icb_cmd_xlen,
  input [1:0]                   icb_cmd_xburst,
  input [1:0]                   icb_cmd_modes,
  input                         icb_cmd_dmode,
  input [2:0]                   icb_cmd_attri,
  input                         icb_cmd_read, 
  input [DW-1:0]                icb_cmd_wdata,
  input [DW/8-1:0]                icb_cmd_wmask,
  input [1:0]                   icb_cmd_beat,
  input                         icb_cmd_lock,
  input                         icb_cmd_excl,
  input [2:0]                   icb_cmd_size,
  input [CMD_UW-1:0]             icb_cmd_usr,
  input                         axi_awready,
  output                        axi_awvalid,
  output [AW-1:0]               axi_awaddr,
  output [7:0]                  axi_awlen,
  output [2:0]                  axi_awsize,
  output [1:0]                  axi_awburst,
  output                        axi_awlock,
  output [3:0]                  axi_awcache,
  output [2:0]                  axi_awprot,
  output [CMD_UW-1:0]            axi_awuser, 
  input                         axi_wready,
  output                        axi_wvalid,
  output [DW-1:0]               axi_wdata,
  output [DW/8-1:0]               axi_wstrb,
  output                        axi_wlast,
  input                         axi_bus_clk_en,
  input                         icb_clk_en,
  input                         clk,
  input                         rst_n
  );
  localparam PACK_A_W = AW+8+3+1+2+4+3+CMD_UW;
  localparam PACK_D_W = DW+DW/8+1;
  wire axi_aw_ready;
  wire axi_w_ready;
  wire burst_flag_r;
  wire burst_flag_en;
  wire burst_flag_set;
  wire burst_flag_clr;
  
  
  
  
  
  
  wire [PACK_A_W-1:0] i_axi_a_pack;
  wire [PACK_A_W-1:0] o_axi_a_pack;
  wire [PACK_D_W-1:0] i_axi_d_pack;
  wire [PACK_D_W-1:0] o_axi_d_pack;
  wire i_axi_a_vld;
  wire i_axi_a_rdy;
  wire o_axi_a_vld;
  wire o_axi_a_rdy;
  wire i_axi_d_vld;
  wire i_axi_d_rdy;
  wire o_axi_d_vld;
  wire o_axi_d_rdy;
  wire                i_awready;
  wire                i_awvalid;
  wire [AW-1:0]       i_awaddr;
  wire [7:0]          i_awlen;
  wire [2:0]          i_awsize;
  wire [1:0]          i_awburst;
  wire                i_awlock;
  wire [3:0]          i_awcache;
  wire [2:0]          i_awprot;
  wire [CMD_UW-1:0]    i_awuser; 
  wire                i_wready;
  wire                i_wvalid;
  wire [DW-1:0]       i_wdata;
  wire [DW/8-1:0]       i_wstrb;
  wire                i_wlast;
  assign axi_aw_ready = axi_awready ;
  assign axi_w_ready  = axi_wready  ;
  assign i_axi_a_pack = 
                      {
                        i_awaddr,
                        i_awlen,
                        i_awsize,
                        i_awburst,
                        i_awlock,
                        i_awcache,
                        i_awprot,
                        i_awuser  
                      };
  assign i_axi_a_vld = i_awvalid;
  assign i_awready = i_axi_a_rdy; 
  assign {
          axi_awaddr,
          axi_awlen,
          axi_awsize,
          axi_awburst,
          axi_awlock,
          axi_awcache,
          axi_awprot,
          axi_awuser  
         } = o_axi_a_pack;
  assign axi_awvalid = o_axi_a_vld;
  assign o_axi_a_rdy = axi_aw_ready;
  assign i_axi_d_pack = 
                      {
                       i_wdata,
                       i_wstrb,
                       i_wlast
                      };
  assign i_axi_d_vld = i_wvalid;
  assign i_wready    = i_axi_d_rdy; 
  assign {
          axi_wdata,
          axi_wstrb,
          axi_wlast
         } = o_axi_d_pack;
  assign axi_wvalid  = o_axi_d_vld;
  assign o_axi_d_rdy = axi_w_ready;
  e603_gnrl_ratio_fifo # (
        .I_SUPPORT_RATIO (1),
        .O_SUPPORT_RATIO (1),
        .DP  (RATIO_FIFO_DP),
        .DW  (PACK_A_W)
  ) u_axi_aw_fifo (
        .i_clk_en(icb_clk_en),
        .i_vld(i_axi_a_vld),
        .i_rdy(i_axi_a_rdy),
        .i_dat(i_axi_a_pack),
        .o_clk_en(axi_bus_clk_en),
        .o_vld(o_axi_a_vld),
        .o_rdy(o_axi_a_rdy),  
        .o_dat(o_axi_a_pack),  
      
        .o_fifo_active(),
        .clk  (clk),
        .rst_n(rst_n)
  );
  e603_gnrl_ratio_fifo # (
        .I_SUPPORT_RATIO (1),
        .O_SUPPORT_RATIO (1),
        .DP  (RATIO_FIFO_DP),
        .DW  (PACK_D_W)
  ) u_axi_w_fifo (
        .i_clk_en(icb_clk_en),
        .i_vld(i_axi_d_vld),
        .i_rdy(i_axi_d_rdy),
        .i_dat(i_axi_d_pack),
        .o_clk_en(axi_bus_clk_en),
        .o_vld(o_axi_d_vld),
        .o_rdy(o_axi_d_rdy),  
        .o_dat(o_axi_d_pack),  
      
        .o_fifo_active(),
        .clk  (clk),
        .rst_n(rst_n)
  );
  assign burst_flag_en = burst_flag_set || burst_flag_clr;
  
  assign burst_flag_set = icb_cmd_ready && icb_cmd_valid && icb_cmd_beat[0] & icb_clk_en;
  assign burst_flag_clr = burst_flag_r && icb_cmd_ready && icb_cmd_valid && icb_cmd_beat[1] & icb_clk_en;
  e603_gnrl_dfflr #(1) burst_flag_dfflr (burst_flag_en, burst_flag_set, burst_flag_r, clk, rst_n);
  assign icb_cmd_ready =   (i_awready || burst_flag_r) && (i_wready);
  assign i_awvalid = icb_cmd_valid && (!burst_flag_r) && i_wready;
  assign i_wvalid  = icb_cmd_valid && (i_awready || burst_flag_r);
  assign i_awaddr   = icb_cmd_addr;
  assign i_awlen     = icb_cmd_xlen[7:0];
  assign i_awburst   = icb_cmd_xburst[1:0];
  assign i_awsize    = icb_cmd_size;
  
  assign i_awlock    = icb_cmd_excl; 
  wire icb_cmd_mmode  = (icb_cmd_modes == 2'd0);
  wire icb_cmd_smode  = (icb_cmd_modes == 2'd2);
  wire icb_cmd_ifu    = icb_cmd_attri[0];
  wire icb_cmd_device = icb_cmd_attri[1];
  wire icb_cmd_nc     = icb_cmd_attri[2];
  assign i_awcache   =  icb_cmd_device ? 4'b0000 :
                          icb_cmd_nc     ? 4'b0011 : 4'b1111;
  assign i_awprot[0] = icb_cmd_mmode | icb_cmd_smode;
  assign i_awprot[1] = 1'b0; 
  assign i_awprot[2] = 1'b0;
  assign i_awuser    = icb_cmd_usr;
  assign i_wdata     = icb_cmd_wdata;
  assign i_wstrb     = icb_cmd_wmask;   
  assign i_wlast    = ((icb_cmd_beat == 2'b00) && !burst_flag_r) || icb_cmd_beat[1];
endmodule
module e603_gnrl_ficb2axi_r # (
  parameter AW = 32,
  parameter DW = 32,
  parameter RATIO_FIFO_DP = 2,
  parameter RSP_UW = 1 
) (
  input                          icb_cmd_cnt_is_0,
  output                         icb_rrsp_valid,
  input                          icb_rrsp_ready,
  output [DW-1:0]                icb_rrsp_rdata,
  output                         icb_rrsp_err,
  output                         icb_rrsp_excl_ok,
  output [RSP_UW-1:0]            icb_rrsp_usr,
  output                         axi_rready,
  input                          axi_rvalid,
  input [RSP_UW-1:0]              axi_ruser,
  input [DW-1:0]                 axi_rdata,
  input [1:0]                    axi_rresp,
  input                          axi_rlast,
  
  input                         axi_bus_clk_en,
  input                         icb_clk_en,
  
  input                         clk,
  input                         rst_n
  );
  localparam PACK_W = DW+2+1+RSP_UW;
  wire                          o_rvalid;
  wire [DW-1:0]                 o_rdata;
  wire [RSP_UW-1:0]              o_rusr;
  wire [1:0]                    o_rresp;
  wire                          o_rlast;
  wire [PACK_W-1:0] i_axi_pack;
  wire [PACK_W-1:0] o_axi_pack;
  wire i_axi_vld;
  wire i_axi_rdy;
  wire o_axi_vld;
  wire o_axi_rdy;
  assign i_axi_pack = 
                      {
                        axi_ruser,
                        axi_rdata,
                        axi_rresp,
                        axi_rlast 
                      };
  assign {
          o_rusr,
          o_rdata,
          o_rresp,
          o_rlast 
         } = o_axi_pack;
  assign o_rvalid = o_axi_vld;
  assign icb_rrsp_valid = (~icb_cmd_cnt_is_0) & o_rvalid      ;
  assign o_axi_rdy      = (~icb_cmd_cnt_is_0) & icb_rrsp_ready;
  assign i_axi_vld = axi_rvalid ;
  assign axi_rready = i_axi_rdy;
  e603_gnrl_ratio_fifo # (
        .I_SUPPORT_RATIO (1),
        .O_SUPPORT_RATIO (1),
        .DP  (RATIO_FIFO_DP),
        .DW  (PACK_W)
  ) u_axi_r_fifo (
        .i_clk_en(axi_bus_clk_en),
        .i_vld(i_axi_vld),
        .i_rdy(i_axi_rdy),
        .i_dat(i_axi_pack),
        .o_clk_en(icb_clk_en),
        .o_vld(o_axi_vld),
        .o_rdy(o_axi_rdy),  
        .o_dat(o_axi_pack),  
      
        .o_fifo_active(),
        .clk  (clk),
        .rst_n(rst_n)
  );
  
  assign icb_rrsp_err     = o_rresp[1] ; 
  assign icb_rrsp_excl_ok = (o_rresp == 2'b01);
  assign icb_rrsp_rdata   = o_rdata;
  assign icb_rrsp_usr     = o_rusr;
endmodule
module e603_gnrl_ficb2axi_b # (
  parameter AW = 32,
  parameter DW = 32,
  parameter RSP_UW = 1,
  parameter RATIO_FIFO_DP = 2 
) (
  input                          wrsp_burst_fifo_o_vld,
  output                         icb_wrsp_valid,
  input                          icb_wrsp_ready,
  output                         icb_wrsp_err,
  output                         icb_wrsp_excl_ok,
  output [RSP_UW-1:0]             icb_wrsp_usr,
  output                         axi_bready,
  input                          axi_bvalid,
  input [1:0]                    axi_bresp,
  input [RSP_UW-1:0]              axi_buser,
  
  input                         axi_bus_clk_en,
  input                         icb_clk_en,
  input [7:0]                   wrsp_xlen,
  output                        wrsp_last,
  input                         clk,
  input                         rst_n
  );
  localparam PACK_W = 2+RSP_UW;
  wire [RSP_UW-1:0]              o_busr;
  wire [1:0]                    o_bresp;
  wire o_burst = (wrsp_xlen != 8'b0);
  wire [PACK_W-1:0] i_axi_pack;
  wire [PACK_W-1:0] o_axi_pack;
  wire i_axi_vld;
  wire i_axi_rdy;
  wire o_axi_vld;
  wire o_axi_rdy;
  wire       burst_last;
  wire [7:0] burst_cnt_r;
  wire [7:0] burst_cnt_r_nxt;
  wire       burst_cnt_ena;
  assign i_axi_pack = 
                      {
                        axi_bresp,
                        axi_buser 
                      };
  assign {
          o_bresp,
          o_busr 
         } = o_axi_pack;
  assign i_axi_vld = axi_bvalid ;
  assign axi_bready = i_axi_rdy;
  e603_gnrl_ratio_fifo # (
        .I_SUPPORT_RATIO (1),
        .O_SUPPORT_RATIO (1),
        .DP  (RATIO_FIFO_DP),
        .DW  (PACK_W)
  ) u_axi_b_fifo (
        .i_clk_en(axi_bus_clk_en),
        .i_vld(i_axi_vld),
        .i_rdy(i_axi_rdy),
        .i_dat(i_axi_pack),
        .o_clk_en(icb_clk_en),
        .o_vld(o_axi_vld),
        .o_rdy(o_axi_rdy),  
        .o_dat(o_axi_pack),  
      
        .o_fifo_active(),
        .clk  (clk),
        .rst_n(rst_n)
  );
  wire burst_first = (burst_cnt_r == 8'd0);
  assign burst_cnt_r_nxt = burst_last ? 8'b0 : (burst_cnt_r + 8'b1);
  assign burst_last = (burst_cnt_r == wrsp_xlen) & (~burst_first);
  assign burst_cnt_ena = o_burst && icb_wrsp_valid && icb_wrsp_ready & icb_clk_en;
  e603_gnrl_dfflr #(8) burst_cnt_dfflr (burst_cnt_ena, burst_cnt_r_nxt, burst_cnt_r, clk, rst_n);
  assign icb_wrsp_valid   = wrsp_last ? o_axi_vld : wrsp_burst_fifo_o_vld;
  assign o_axi_rdy = icb_wrsp_ready && wrsp_last;
  assign icb_wrsp_err     = wrsp_last ? o_bresp[1]         : 1'b0;
  assign icb_wrsp_excl_ok = wrsp_last ? (o_bresp == 2'b01) : 1'b0;
  assign icb_wrsp_usr     = wrsp_last ? o_busr : {RSP_UW{1'b0}};
  assign wrsp_last = burst_last | (wrsp_xlen == 8'd0);
endmodule
module e603_gnrl_ficb2axi_read # (
  parameter AW = 32,
  parameter DW = 32,
  parameter RATIO_FIFO_DP = 2,
  parameter OUTS_CNT_W = 4,
  parameter CMD_UW = 1,
  parameter RSP_UW = 1
  ) (
  
  input                         axi_arready,
  output                        axi_arvalid,
  output [AW-1:0]               axi_araddr,
  output [7:0]                  axi_arlen,
  output [2:0]                  axi_arsize,
  output [1:0]                  axi_arburst,
  output                        axi_arlock,
  output [3:0]                  axi_arcache,
  output [2:0]                  axi_arprot,
  output [CMD_UW-1:0]            axi_aruser,
  
  output                        axi_rready,
  input                         axi_rvalid,
  input [DW-1:0]                axi_rdata,
  input [RSP_UW-1:0]             axi_ruser,
  input [1:0]                   axi_rresp,
  input                         axi_rlast,
  input                         axi_bus_clk_en,
  input                         icb_clk_en,
  
  input                         icb_cmd_sel,
  input                         icb_cmd_valid,
  output                        icb_cmd_ready,
  input [AW-1:0]                icb_cmd_addr, 
  input                         icb_cmd_read, 
  input [DW-1:0]                icb_cmd_wdata,
  input [DW/8-1:0]                icb_cmd_wmask,
  input [CMD_UW-1:0]             icb_cmd_usr,
  input [1:0]                   icb_cmd_beat,
  input                         icb_cmd_lock,
  input                         icb_cmd_excl,
  input [2:0]                   icb_cmd_size,
  input [7:0]                   icb_cmd_xlen,
  input [1:0]                   icb_cmd_xburst,
  input [1:0]                   icb_cmd_modes,
  input                         icb_cmd_dmode,
  input [2:0]                   icb_cmd_attri,
  
  output                        icb_rsp_valid,
  input                         icb_rsp_ready,
  output                        icb_rsp_err  ,
  output                        icb_rsp_excl_ok,
  output [DW-1:0]               icb_rsp_rdata,
  output [RSP_UW-1:0]            icb_rsp_usr,
  input                         clk,
  input                         rst_n
  );
  
  
  localparam CNT_W = 8;
  wire outs_cnt_inc = icb_cmd_valid & icb_cmd_ready & icb_clk_en;
  wire outs_cnt_dec = icb_rsp_valid & icb_rsp_ready & icb_clk_en;
     
  wire outs_cnt_ena = outs_cnt_inc ^ outs_cnt_dec;
     
  wire [CNT_W-1:0] outs_cnt_r;
  wire [CNT_W-1:0] outs_cnt_nxt = outs_cnt_inc ? (outs_cnt_r + 1'b1) : (outs_cnt_r - 1'b1);
  e603_gnrl_dfflr #(CNT_W) outs_cnt_dfflr (outs_cnt_ena, outs_cnt_nxt, outs_cnt_r, clk, rst_n);
  wire icb_cmd_cnt_full = (outs_cnt_r == {CNT_W{1'b1}});
  wire icb_cmd_cnt_is_0 = (outs_cnt_r == {CNT_W{1'b0}});
  wire icb_cmd_valid_raw;
  wire icb_cmd_ready_raw;
  assign icb_cmd_valid_raw = (~icb_cmd_cnt_full) & icb_cmd_valid;
  assign icb_cmd_ready     = (~icb_cmd_cnt_full) & icb_cmd_ready_raw;
  e603_gnrl_ficb2axi_ar # (
            .AW (AW),
            .DW (DW),
            .RATIO_FIFO_DP(RATIO_FIFO_DP),
            .CMD_UW (CMD_UW)
   ) u_icb2axi_ar(
            .icb_cmd_valid (icb_cmd_valid_raw),
            .icb_cmd_ready (icb_cmd_ready_raw),
            .icb_cmd_addr (icb_cmd_addr), 
            .icb_cmd_sel  (icb_cmd_sel), 
            .icb_cmd_xlen(icb_cmd_xlen),
            .icb_cmd_xburst(icb_cmd_xburst),
            .icb_cmd_modes (icb_cmd_modes ),
            .icb_cmd_dmode (icb_cmd_dmode ),
            .icb_cmd_attri (icb_cmd_attri ),
            .icb_cmd_read (icb_cmd_read), 
            .icb_cmd_wdata (icb_cmd_wdata),
            .icb_cmd_wmask (icb_cmd_wmask),
            .icb_cmd_beat (icb_cmd_beat),
            .icb_cmd_lock (icb_cmd_lock),
            .icb_cmd_excl (icb_cmd_excl),
            .icb_cmd_size (icb_cmd_size),
            .icb_cmd_usr (icb_cmd_usr),
            .axi_arready (axi_arready),
            .axi_arvalid (axi_arvalid),
            .axi_araddr (axi_araddr),
            .axi_arlen (axi_arlen),
            .axi_arsize (axi_arsize),
            .axi_arburst (axi_arburst),
            .axi_arlock (axi_arlock),
            .axi_arcache (axi_arcache),
            .axi_arprot (axi_arprot),
            .axi_aruser (axi_aruser),
            .axi_bus_clk_en (axi_bus_clk_en),
            .icb_clk_en (icb_clk_en),
            .clk (clk),
            .rst_n (rst_n)
  );
  e603_gnrl_ficb2axi_r # (
            .AW (AW),
            .DW (DW),
            .RATIO_FIFO_DP(RATIO_FIFO_DP),
            .RSP_UW (RSP_UW) 
  ) u_icb2axi_r(
            .icb_cmd_cnt_is_0(icb_cmd_cnt_is_0),
            .icb_rrsp_valid (icb_rsp_valid),
            .icb_rrsp_ready (icb_rsp_ready),
            .icb_rrsp_rdata (icb_rsp_rdata),
            .icb_rrsp_usr (icb_rsp_usr),
            .icb_rrsp_err (icb_rsp_err),
            .icb_rrsp_excl_ok (icb_rsp_excl_ok),
            .axi_rready (axi_rready),
            .axi_rvalid (axi_rvalid),
            .axi_rdata (axi_rdata),
            .axi_ruser (axi_ruser),
            .axi_rresp (axi_rresp),
            .axi_rlast (axi_rlast),
  
            .axi_bus_clk_en (axi_bus_clk_en),
            .icb_clk_en (icb_clk_en),
            .clk (clk),
            .rst_n (rst_n)
  );
endmodule
module e603_gnrl_ficb2axi_write # (
  parameter AW = 32,
  parameter DW = 32,
  parameter OUTS_FIFO_DP =4,
  parameter RATIO_FIFO_DP =2,
  parameter CMD_UW = 1,
  parameter RSP_UW = 1
) (
  output                        icb2axi_write_pend_active,
  
  input                         axi_awready,
  output                        axi_awvalid,
  output [AW-1:0]               axi_awaddr,
  output [7:0]                  axi_awlen,
  output [2:0]                  axi_awsize,
  output [1:0]                  axi_awburst,
  output                        axi_awlock,
  output [3:0]                  axi_awcache,
  output [2:0]                  axi_awprot,
