            .axi_bvalid (axi_bvalid),
            .axi_bresp (axi_bresp),
            .axi_buser (axi_buser),
            .axi_bid (axi_bid),
  
            .axi_bus_clk_en (axi_bus_clk_en),
            .icb_clk_en (icb_clk_en),
            .wrsp_xlen  (wrsp_xlen),
            .wrsp_last  (wrsp_last),
            .wrsp_id    (wrsp_id  ),
            .clk (clk),
            .rst_n (rst_n)
  );
  assign icb2axi_write_pend_active = wrsp_burst_fifo_o_vld | axi_wvalid | axi_awvalid;
  
endmodule
