module e603_gnrl_ficb2axi_read_async_id # (
  parameter ID_W = 32,
  parameter AW = 32,
  parameter DW = 32,
  parameter OUTS_CNT_W = 4,
  parameter SYNC_DP = 2,
  parameter ASYNC_FIFO = 0,
  parameter ASYNC_FIFO_DP = 4,
