    .icb_wcmd_attri   (icb_wcmd_attri  ),
    .icb_wcmd_usr   (icb_wcmd_usr  ), 
    .clk (clk),
    .rst_n (rst_n)
  );
    
    localparam AXI_B_BUF_PACK = ID_W+2;
    wire [ID_W-1:0]    axi_buf_i_bid    ; 
    wire [1:0]                  axi_buf_i_bresp  ; 
