                                             axi_arid    ,  
                                             axi_araddr  ,
                                             axi_arlen   ,
                                             axi_arsize  ,
                                             axi_arburst ,
                                             axi_arlock  ,
                                             axi_arcache ,
                                             axi_arprot  ,
                                             axi_aruser   
                                            };
