module e603_gnrl_sdp_ram (wclk, wrst_n, wr, waddr, wdata, rclk, rrst_n, rd, raddr, rdata);
  parameter DW = 8;
  parameter DP = 4;
  parameter DP_PTR_W = 2;
  parameter REG_OUT = 1;
  localparam AW = (DP <= 1) ? 1 : DP_PTR_W;
  input           wclk;
  input           wrst_n;
  input           wr;
  input  [AW-1:0] waddr;
  input  [DW-1:0] wdata;
  input           rclk;
  input           rrst_n;
  input           rd;
  input  [AW-1:0] raddr;
  output [DW-1:0] rdata;
  wire    [DP-1:0] wword_line, rword_line;
  wire [DP*DW-1:0] mem;
  wire    [DW-1:0] rdata_int;
  wire    [DW-1:0] rdata;
  genvar gvi;
  generate
  for (gvi=0; gvi<DP; gvi=gvi+1) begin: GEN_WWORD_LINE
    assign wword_line[gvi] = wr & (waddr == gvi[AW-1:0]);
  end 
  endgenerate
  e603_gnrl_mem_line #(
  .DW(DW))
  U_mem_line [DP-1:0] (
  .clk(wclk),
  .rst_n(wrst_n),
  .wr(wword_line),
  .wdata(wdata),
  .mem(mem)
  );
  e603_gnrl_data_mux #(.DW(DW), .N(DP))
  U_rdata_mux (
  .out_data(rdata_int),
  .in_data(mem),
  .sel(raddr)
  );
  generate
  if (REG_OUT > 0) begin: REG_OUT_1
    e603_gnrl_dfflr #(DW) rdata_dfflr (rd, rdata_int, rdata, rclk, rrst_n);
  end 
  else begin: REG_OUT_0
    assign rdata = rdata_int;
  end 
  endgenerate
endmodule
module e603_gnrl_dp_2clk_ram (clkgate_bypass, sd, ds, ls, wclk, wrst_n, wr, wem, waddr, wdata, rclk, rrst_n, rd, raddr, rdata);
  parameter DW = 8;
  parameter DP = 4;
  parameter MW = 1;
  parameter AW = 1;
  parameter GATE_CLK = 1;
  parameter FORCE_X2ZERO = 0;
  input            sd;
  input            ds;
  input            ls;
  input           clkgate_bypass;
  input           wclk;
  input           wrst_n;
  input           wr;
  input  [MW-1:0] wem;
  input  [AW-1:0] waddr;
  input  [DW-1:0] wdata;
  input           rclk;
  input           rrst_n;
  input           rd;
  input  [AW-1:0] raddr;
  output [DW-1:0] rdata;
  wire wclk_cg;
  wire rclk_cg;
  generate
  if (GATE_CLK == 1)
  begin: gate_clk_1_gen
  e603_clkgate u_rclk_clkgate(
    .clk_in   (rclk),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (rd),
    .clk_out  (rclk_cg )
  );
  e603_clkgate u_wclk_clkgate(
    .clk_in   (wclk),
    .clkgate_bypass(clkgate_bypass  ),
    .clock_en (wr),
    .clk_out  (wclk_cg )
  );
  end else begin: gate_clk_0_gen
    assign wclk_cg = wclk;
    assign rclk_cg = rclk;
  end
  endgenerate
`ifdef SYNTHESIS
e603_gnrl_tech_dp_2clk_ram #(
    .FORCE_X2ZERO (FORCE_X2ZERO),
    .DP (DP),
    .AW (AW),
    .MW (MW),
    .DW (DW) 
)u_ram (
    .sd             (sd             ),
    .ds             (ds             ),
    .ls             (ls             ),
    .wclk           (wclk_cg        ), 
    .wrst_n         (wrst_n         ), 
    .wr             (wr             ), 
    .wem            (wem            ),
    .waddr          (waddr          ), 
    .din            (wdata          ), 
    .rclk           (rclk_cg        ), 
    .rrst_n         (rrst_n         ), 
    .rd             (rd             ), 
    .raddr          (raddr          ), 
    .dout           (rdata          )
);
`else
  e603_sim_dpram #(
    .FORCE_X2ZERO (FORCE_X2ZERO),
    .DP (DP),
    .AW (AW),
    .MW (MW),
    .DW (DW) 
  ) u_ram (
    .wclk           (wclk_cg        ), 
    .wcs            (wr             ), 
    .waddr          (waddr          ), 
    .wdin           (wdata          ), 
    .wmask          (wem            ),
    .rclk           (rclk_cg        ), 
    .rcs            (rd             ), 
    .raddr          (raddr          ), 
    .rdout          (rdata          )
    );
`endif
endmodule
module e603_gnrl_dp_1clk_ram (clkgate_bypass, sd, ds, ls, clk, rst_n, wr, wem, waddr, wdata, rd, raddr, rdata);
  parameter DW = 8;
  parameter DP = 4;
  parameter MW = 1;
