module e603_gnrl_age_matrix_dual_issue #(
    parameter ENT_NUM = 4
    ) (
    input [ENT_NUM-1:0]           entry_alloc_en,
    output [ENT_NUM*ENT_NUM-1:0]  age_matrix_pack,
    input clk,
    input rst_n
    );
  genvar i,j;
  wire [ENT_NUM-1:0] older_matrix_ena  [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] older_matrix_next [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] older_matrix      [ENT_NUM-1:0];
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :older_1d
      for (j=0;j<ENT_NUM;j=j+1) begin :older_2d
        if (i < j) begin: bottem_left
          
          assign older_matrix_ena[i][j] = entry_alloc_en[i] || entry_alloc_en[j];
          assign older_matrix_next[i][j]= entry_alloc_en[i] ? ~entry_alloc_en[j] :
                                          entry_alloc_en[j] ? 1'b0 :
                                                            1'b0 ;
          e603_gnrl_dfflr #(1) age_r (older_matrix_ena[i][j], older_matrix_next[i][j], older_matrix[i][j], clk, rst_n);
        end 
        else begin: top_right
          assign older_matrix_ena[i][j] = 1'b0;
          assign older_matrix_next[i][j] = 1'b0;
          assign older_matrix[i][j] = 1'b0;
        end
      end
    end
  endgenerate
 
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :gen_age_matrix
      assign age_matrix_pack[i*ENT_NUM+:ENT_NUM] = older_matrix[i][ENT_NUM-1:0];
    end
  endgenerate 
endmodule
module e603_gnrl_age_matrix_comb #(
    parameter ENT_NUM = 4
    ) (
    input [ENT_NUM-1:0]           alc_en,
    input [ENT_NUM*ENT_NUM-1:0]   am_init,
    output [ENT_NUM*ENT_NUM-1:0]  am_update 
    );
  wire [ENT_NUM-1:0] pre_update      [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] pos_update      [ENT_NUM-1:0];
  genvar i,j;
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :fold_age_matrix
      assign pre_update[i][ENT_NUM-1:0] = am_init[i*ENT_NUM+:ENT_NUM] ;
    end
  endgenerate 
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :older_1d
      for (j=0;j<ENT_NUM;j=j+1) begin :older_2d
        if (i < j) begin: bottem_left
          
          assign pos_update[i][j]= alc_en[i] ? 1'b1 :
                                  alc_en[j] ? 1'b0 : 
                                          pre_update[i][j] ;
        end 
        else begin: top_right
          assign pos_update[i][j] = 1'b0;
        end
      end
    end
  endgenerate
  generate
    for (i=0;i<ENT_NUM;i=i+1) begin :gen_age_matrix
      assign am_update[i*ENT_NUM+:ENT_NUM] = pos_update[i][ENT_NUM-1:0];
    end
  endgenerate 
endmodule
module e603_gnrl_age_matrix_dff #(
    parameter ENT_NUM = 4
    ) (
    input [ENT_NUM-1:0]           alc_en,
    input [ENT_NUM*ENT_NUM-1:0]   am_nxt,
    output [ENT_NUM*ENT_NUM-1:0]  am_r,
    input clk,
    input rst_n
    );
  wire [ENT_NUM-1:0] alc_en_final  [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] alc_nxt [ENT_NUM-1:0];
  wire [ENT_NUM-1:0] alc_am  [ENT_NUM-1:0];
